INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_air-fryer-honey-mustard-pork_v1', 1, 'Preheat the air fryer and make the glaze', 'Set the air fryer to 400 F and let it preheat about 3 minutes. Those 3 minutes are inside the cook time. Meanwhile, whisk the Dijon mustard, honey, apple cider vinegar, minced garlic, most of the olive oil (reserve 1 tsp), 1/4 tsp of the kosher salt, 1/4 tsp of the black pepper, and the smoked paprika into a smooth honey-mustard glaze. This glaze is made here. It is not a bottled honey-mustard salad dressing and not a soy-based teriyaki. Trim silver skin from the pork tenderloin and pat it dry. Rub with the remaining 1 tsp olive oil, then season with the remaining 3/4 tsp kosher salt and 1/4 tsp black pepper.', '["dijon-mustard","honey","apple-cider-vinegar","garlic","olive-oil","kosher-salt","black-pepper","smoked-paprika","pork-tenderloin"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_air-fryer-honey-mustard-pork_v1', 2, 'Air-fry the first stretch', 'Place the seasoned pork tenderloin in the air-fryer basket. Air-fry at 400 F for 10 minutes. The air fryer is the primary equipment; do not move this cook to a sheet pan unless you are abandoning this package method.', '["pork-tenderloin"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_air-fryer-honey-mustard-pork_v1', 3, 'Glaze and finish', 'Brush about two-thirds of the honey-mustard glaze over the pork. Air-fry 6 to 8 minutes more at 400 F, until an instant-read thermometer in the thickest center reads 145 F and the glaze looks sticky and browned in patches. If the tenderloin is thick and still under 145 F at 8 minutes, continue in 2-minute checks; extra time beyond the written window is not inside the 35-minute total. Brush with the remaining glaze in the last 2 minutes if it looks dry. kitchen_tested is false.', '["pork-tenderloin","dijon-mustard","honey"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_air-fryer-honey-mustard-pork_v1', 4, 'Rest and slice', 'Transfer the pork to a cutting board. Rest 5 minutes (inside cook time). Slice into 1/2-inch medallions. Spoon any glaze from the board over the slices. Scatter optional parsley if using. No flour dredge. No egg wash. No breadcrumbs.', '["pork-tenderloin","fresh-parsley"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_black-bean-quesadillas_v1', 1, 'Fill', 'Mix beans, cumin, half the cheese. Spread on tortillas, top with cheese, fold.', '["black beans","shredded cheese"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_black-bean-quesadillas_v1', 2, 'Crisp', 'Cook quesadillas in oiled skillet over medium heat 2–3 min per side until golden.', '["flour tortillas","neutral oil"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_black-bean-quesadillas_v1', 3, 'Serve', 'Cut into wedges; serve with salsa.', '["salsa"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_black-bean-quesadillas_v2', 1, 'Fill', 'Mix beans, cumin, half the cheese. Spread on tortillas, top with cheese, fold.', '["black beans","cumin","shredded cheese","flour tortillas"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_black-bean-quesadillas_v2', 2, 'Crisp', 'Cook quesadillas in oiled skillet over medium heat 2–3 min per side until golden.', '["flour tortillas","neutral oil"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_black-bean-quesadillas_v2', 3, 'Serve', 'Cut into wedges; serve with salsa.', '["salsa"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_cajun-blackened-catfish_v1', 1, 'Mix the blackening rub and make the remoulade', 'Stir together the sweet paprika, cayenne, garlic powder, onion powder, dried thyme, dried oregano, 1 tsp of the kosher salt, and 1/2 tsp of the black pepper. In a separate bowl, whisk the egg mayonnaise with the Dijon mustard, lemon juice, 1 tbsp of the neutral oil, dill pickle relish, chopped capers, parsley, chives, garlic paste, hot sauce, the remaining 1/4 tsp kosher salt, and the remaining 1/4 tsp black pepper. This herb remoulade is made here. It is not a bottled remoulade. Confirm the mayonnaise has no milk, buttermilk, or cream. Chill the remoulade while the fish cooks. Pat the catfish fillets dry.', '["sweet-paprika","cayenne-pepper","garlic-powder","onion-powder","dried-thyme","dried-oregano","kosher-salt","black-pepper","egg-mayonnaise","dijon-mustard","lemon-juice","neutral-oil","dill-pickle-relish","capers","fresh-parsley","fresh-chives","garlic","hot-sauce","catfish-fillets"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_cajun-blackened-catfish_v1', 2, 'Coat the catfish', 'Press both sides of each catfish fillet into the blackening rub so the spices adhere in an even coat. Shake off only the loosest excess. Do not flour the fish. Do not egg-wash it. Do not bread it.', '["catfish-fillets","sweet-paprika","cayenne-pepper","garlic-powder","onion-powder","dried-thyme","dried-oregano","kosher-salt","black-pepper"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_cajun-blackened-catfish_v1', 3, 'Blacken in a hot skillet', 'Heat a 12-inch cast-iron or heavy stainless skillet over medium-high until it is very hot, about 3 minutes. Add 2 tbsp of the neutral oil and swirl. Lay in as many fillets as fit without crowding (often 2). Cook undisturbed until the spice crust is darkened and fragrant and the edges look opaque, about 3 to 4 minutes. Flip once. Cook the second side about 3 to 4 minutes more, until the thickest part flakes and is opaque (about 145 F if checked). Move cooked fillets to a warm plate. Add a thin film of the remaining oil if the pan is dry and cook the remaining fillets the same way. The written clock uses one 3-minute preheat plus two batches of about 7 minutes each (14) overlapping the plate-hold; cook_minutes below uses 17 for preheat + batch work. Do not deep-fry. Do not bake. kitchen_tested is false.', '["neutral-oil","catfish-fillets"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_cajun-blackened-catfish_v1', 4, 'Plate with remoulade', 'Serve each blackened catfish fillet with a spoonful of the dairy-free herb remoulade on the side or a stripe on the plate. No butter basting. No buttermilk soak. No nuts. No breaded coating.', '["catfish-fillets","egg-mayonnaise","dijon-mustard","fresh-parsley"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_cashew-pesto-pasta_v1', 1, 'Blend pesto', 'Blend cashews, basil, garlic, lemon, yeast, salt, and ¼ cup water until smooth.', '["raw cashews","basil"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_cashew-pesto-pasta_v1', 2, 'Cook pasta', 'Boil pasta until al dente; reserve ½ cup pasta water.', '["short pasta"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_cashew-pesto-pasta_v1', 3, 'Toss & serve', 'Toss pasta with pesto, splashes of pasta water, and tomatoes.', '["cherry tomatoes"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_cashew-pesto-pasta_v2', 1, 'Soak and blend the pesto', 'Cover the cashews with boiling water and soak 20 minutes, then drain. Blend the drained cashews with the basil, garlic, lemon juice, nutritional yeast, kosher salt, and 1/4 cup fresh water until smooth. No oil and no cheese.', '["raw cashews","basil","garlic","lemon juice","nutritional yeast","kosher salt","water"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_cashew-pesto-pasta_v2', 2, 'Cook the pasta', 'Boil the durum wheat pasta until al dente. Reserve 1/2 cup pasta water, then drain.', '["short pasta"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_cashew-pesto-pasta_v2', 3, 'Toss and serve', 'Toss the pasta with the pesto, splashes of the reserved pasta water, and the halved cherry tomatoes.', '["cherry tomatoes","short pasta"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_chipotle-lime-black-bean-bowls_v1', 1, 'Warm beans', 'Simmer beans with chipotle and lime juice.', '["black beans","chipotle in adobo"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_chipotle-lime-black-bean-bowls_v1', 2, 'Assemble', 'Layer quinoa, beans, corn, and toppings.', '["quinoa","corn"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_chipotle-lime-black-bean-bowls_v2', 1, 'Cook the quinoa', 'Rinse the dry quinoa. Simmer it covered in the water about 15 minutes, until the grains are tender, a white ring just shows, and the water is absorbed. Rest covered 5 minutes, then fluff. This is quinoa, not rice.', '["quinoa","water"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_chipotle-lime-black-bean-bowls_v2', 2, 'Simmer the beans', 'Simmer the drained beans with the minced chipotle, the 1 tbsp adobo sauce, and the juice of 1 lime for 10 minutes, until the beans are hot and coated. They should not be soupy and they should not be dry. Cut the second lime into wedges. Start the beans while the quinoa cooks so the 10 minutes sit inside the quinoa clock.', '["black beans","chipotle in adobo","lime"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_chipotle-lime-black-bean-bowls_v2', 3, 'Assemble', 'Layer the quinoa, the beans, and the corn kernels. Add the lime wedges. Do not add toppings. v1 said toppings and named none.', '["quinoa","black beans","corn","lime"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_cider-braised-pork-shoulder_v1', 1, 'Heat the oven and season', 'Heat the oven to 325 F. Pat the boneless pork shoulder dry. Season it on all sides with 2 tsp of the kosher salt and the black pepper. If the piece flaps into two thin tails, tie it with cotton kitchen twine. If it is already one compact piece, do not tie it. The twine is equipment, not an ingredient.', '["boneless-pork-shoulder","kosher-salt","black-pepper"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_cider-braised-pork-shoulder_v1', 2, 'Sear', 'Set a Dutch oven over medium-high heat. Add 1 tbsp of the olive oil. Sear the boneless pork shoulder on all sides until deeply browned, about 8 minutes. Move the pork to a plate. Do not wipe out the fond.', '["olive-oil","boneless-pork-shoulder"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_cider-braised-pork-shoulder_v1', 3, 'Build the braise', 'Add the yellow onion, the apple wedges, the garlic, and the fresh thyme to the pot. Stir 4 minutes, until the onion softens. Add the apple cider, 1/2 cup of the water, and 2 tbsp of the dijon mustard. Return the pork. The liquid should come about halfway up the meat. If the pot is so wide that the liquid sits below one-third of the height, move to a smaller pot. Do not pour in a second carton of cider.', '["yellow-onion","apple","garlic","fresh-thyme","apple-cider","water","dijon-mustard","boneless-pork-shoulder"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_cider-braised-pork-shoulder_v1', 4, 'Braise', 'Cover and put the pot in the 325 F oven. Start checking at 2 hours 30 minutes. It is done at 2 hours 30 minutes to 2 hours 45 minutes, when the center is 195-203 F and a fork slides in with little resistance. The published cook time uses the long end, 2 hours 45 minutes. A shoulder that is tender at 2 hours 30 minutes finishes 15 minutes sooner. 145 F is not the target for this cut.', '["boneless-pork-shoulder"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_cider-braised-pork-shoulder_v1', 5, 'Rest and reduce', 'Move the boneless pork shoulder to a board and rest it 15 minutes. Discard the fresh thyme sprigs. While it rests, boil the pot liquid over medium-high until it coats a spoon, about 8 to 10 minutes. You want about 1 cup. Mash the soft apple into the sauce. Do not add flour. If a thick cap of fat is on the surface, skim it. This reduction shares the rest window with the cabbage and needs a second burner.', '["apple","fresh-thyme","boneless-pork-shoulder"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_cider-braised-pork-shoulder_v1', 6, 'Cook the cabbage', 'During that same rest, heat a 12-inch skillet over medium. Add the remaining 1 tbsp olive oil. Lay in the 8 green cabbage wedges, cut side down, for 3 minutes, until the cut face browns. Turn them. Add the remaining 1/4 cup water, the apple cider vinegar, the remaining 1 tbsp dijon mustard, and the remaining 1/2 tsp kosher salt. Cover 4 minutes, until the core is tender to a knife. Uncover if the skillet is watery. One burner instead of two adds about 10 minutes after the sauce; the published total is the two-burner clock.', '["green-cabbage","olive-oil","water","apple-cider-vinegar","dijon-mustard","kosher-salt"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_cider-braised-pork-shoulder_v1', 7, 'Slice and serve', 'Remove any twine. If the boneless pork shoulder holds, cut 1/2-inch slices against the grain. If it collapses, pull large chunks. Do not puree it and do not shred it into a fine pile. Spoon the cider sauce and the soft apple over the pork. Sprinkle the fresh parsley. Serve the green cabbage wedges beside the meat. No bread and no potatoes.', '["boneless-pork-shoulder","apple","fresh-parsley","green-cabbage"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_citrus-fennel-arctic-char_v1', 1, 'Roast fennel', 'Roast fennel with orange juice 15 min at 400°F.', '["fennel bulb","orange"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_citrus-fennel-arctic-char_v1', 2, 'Cook char', 'Nestle char on pan; roast 10–12 min more until just opaque in the thickest part.', '["arctic char fillets"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_citrus-fennel-arctic-char_v1', 3, 'Finish', 'Top with dill and zest.', '["dill"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_citrus-fennel-arctic-char_v2', 1, 'Roast the fennel', 'Preheat the oven to 400 F. While it heats, toss the fennel with the olive oil, 1/2 tsp kosher salt, and 2 tbsp of the orange juice and spread it on a sheet pan. Once the oven is hot, roast 15 minutes, until the edges soften and start to brown. This is an oven roast. v1''s method list said stovetop, and the steps never use a burner.', '["fennel bulb","olive oil","kosher salt","orange"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_citrus-fennel-arctic-char_v2', 2, 'Cook the char', 'Pat the arctic char dry. Season with the remaining 1/4 tsp kosher salt and the black pepper. Nestle the fillets skin-side down on the fennel. Roast 10-12 minutes more, until the thickest part is just opaque, flakes with a fork, and reads 140-145 F. If a fillet is thinner than 1 inch, pull it at the early end of that range, still at just opaque. Not chalky.', '["arctic char fillets","kosher salt","black pepper"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_citrus-fennel-arctic-char_v2', 3, 'Finish', 'Top with the fresh dill and the orange zest. Spoon on the remaining orange juice. Four servings, one fillet each.', '["fresh dill","orange"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_coconut-chickpea-curry_v1', 1, 'Sweat aromatics', 'Sauté onion in oil until soft. Add garlic and curry powder; cook 1 minute.', '["yellow onion","garlic","curry powder","neutral oil"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_coconut-chickpea-curry_v1', 2, 'Simmer curry', 'Stir in tomato paste, chickpeas, coconut milk, and ½ cup water. Simmer 15 min until thickened.', '["canned chickpeas","coconut milk","tomato paste"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_coconut-chickpea-curry_v1', 3, 'Finish & serve', 'Fold in spinach until wilted. Season and serve over rice.', '["baby spinach","basmati rice"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_coconut-chickpea-curry_v2', 1, 'Sweat the aromatics', 'Sauté the onion in the oil with 1/2 tsp kosher salt until soft, about 7 minutes. Add the garlic and curry powder and cook 1 minute.', '["yellow onion","neutral oil","kosher salt","garlic","curry powder"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_coconut-chickpea-curry_v2', 2, 'Simmer the curry', 'Stir in the tomato paste, chickpeas, coconut milk, and 1/2 cup water. Simmer 15 minutes until the sauce coats the chickpeas. Cook the basmati during this simmer.', '["tomato paste","canned chickpeas","coconut milk","water","basmati rice"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_coconut-chickpea-curry_v2', 3, 'Finish and serve', 'Fold in the spinach until wilted. Season with the remaining 1/2 tsp kosher salt and the black pepper. Serve over the rice.', '["baby spinach","kosher salt","black pepper","basmati rice"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_crispy-chipotle-tofu-tacos_v1', 1, 'Press & season tofu', 'Press tofu 10–15 min, cube into ¾-inch pieces, and pat dry. Toss with oil, cornstarch, chipotle, paprika, cumin, garlic powder, salt, and pepper until coated.', '["extra-firm tofu","neutral oil","cornstarch","chipotle powder"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_crispy-chipotle-tofu-tacos_v1', 2, 'Crisp the tofu', 'Air fry at 400°F for 14–18 minutes, shaking halfway, until deep golden. Skillet option: medium-high 8–10 min, turning. Finish with juice of ½ lime.', '["extra-firm tofu","lime"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_crispy-chipotle-tofu-tacos_v1', 3, 'Make lime slaw', 'Toss cabbage, carrot, cilantro, juice of 1 lime, a drizzle of oil, salt, and pepper. Rest 5 minutes.', '["green cabbage","carrot","cilantro","lime"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_crispy-chipotle-tofu-tacos_v1', 4, 'Warm tortillas & build', 'Warm tortillas in a dry skillet 20–30 sec per side. Build tacos with tofu, slaw, and avocado. Serve with lime wedges.', '["corn tortillas","avocado","lime"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_crispy-chipotle-tofu-tacos_v2', 1, 'Press and prep', 'Press the tofu for 15 minutes. That press is the prep window: shred the cabbage, grate the carrot, chop the cilantro, and juice the limes while it presses. Cut the tofu into 3/4-inch cubes and pat dry.', '["extra-firm tofu","green cabbage","carrot","cilantro","lime"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_crispy-chipotle-tofu-tacos_v2', 2, 'Season the tofu', 'Toss the cubes with 1 tbsp neutral oil, the cornstarch, chipotle powder, smoked paprika, cumin, garlic powder, 1/2 tsp kosher salt, and 1/4 tsp black pepper until coated.', '["neutral oil","cornstarch","chipotle powder","smoked paprika","ground cumin","garlic powder","kosher salt","black pepper"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_crispy-chipotle-tofu-tacos_v2', 3, 'Crisp the tofu', 'Air fry at 400°F for 14–18 minutes, shaking halfway, until deep golden. Skillet option: medium-high heat 8–10 minutes, turning. Finish with the juice of 1/2 lime.', '["extra-firm tofu","lime"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_crispy-chipotle-tofu-tacos_v2', 4, 'Make the lime slaw', 'Toss the cabbage, carrot, and cilantro with the juice of 1 lime, the remaining 2 tsp neutral oil, 1/4 tsp kosher salt, and 1/4 tsp black pepper. Rest 5 minutes. Do this during the end of the air fry so it stays inside the cook time.', '["green cabbage","carrot","cilantro","lime","neutral oil","kosher salt","black pepper"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_crispy-chipotle-tofu-tacos_v2', 5, 'Warm tortillas and build', 'Warm the tortillas in a dry skillet 20–30 seconds per side. Build each taco with tofu, slaw, and avocado. Serve with the remaining 1/2 lime cut into wedges.', '["corn tortillas","avocado","lime"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_crispy-fish-tacos-cabbage-slaw_v1', 1, 'Prep slaw', 'Toss cabbage, carrot, cilantro, juice of 1 lime, salt, and pepper. Rest 5 min.', '["green cabbage","carrot","cilantro","lime"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_crispy-fish-tacos-cabbage-slaw_v1', 2, 'Coat & crisp fish', 'Pat cod dry; dredge in cornmeal, paprika, salt, and pepper. Pan-fry in 2 tbsp oil over medium-high 3–4 min per side until golden and flakes easily.', '["cod fillets","cornmeal","smoked paprika","neutral oil"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_crispy-fish-tacos-cabbage-slaw_v1', 3, 'Warm tortillas', 'Warm tortillas in a dry skillet 20–30 sec per side over medium heat.', '["corn tortillas"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_crispy-fish-tacos-cabbage-slaw_v1', 4, 'Build tacos', 'Fill tortillas with fish, slaw, and crema. Serve with lime wedges.', '["corn tortillas","dairy-free crema","lime"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_crispy-fish-tacos-cabbage-slaw_v2', 1, 'Prep the slaw', 'Toss the green cabbage, carrot, cilantro, the juice of 1 lime, 1/2 tsp of the kosher salt, and 1/4 tsp of the black pepper. Rest 5 minutes.', '["green cabbage","carrot","cilantro","lime","kosher salt","black pepper"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_crispy-fish-tacos-cabbage-slaw_v2', 2, 'Coat and crisp the fish', 'Pat the cod dry. Dredge the strips in the cornmeal, smoked paprika, the remaining 1/2 tsp kosher salt, and the remaining 1/4 tsp black pepper. Pan-fry in 2 tbsp neutral oil over medium-high heat, 3-4 minutes per side, until the crust is golden and the center of a strip is opaque, flakes easily, and reaches 145 F. Add up to 1 tbsp more oil if a second batch looks dry. No egg and no wheat flour in the dredge.', '["cod fillets","cornmeal","smoked paprika","kosher salt","black pepper","neutral oil"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_crispy-fish-tacos-cabbage-slaw_v2', 3, 'Warm the tortillas', 'Warm the corn tortillas in a dry skillet 20-30 seconds per side over medium heat.', '["corn tortillas"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_crispy-fish-tacos-cabbage-slaw_v2', 4, 'Build the tacos', 'If using store-bought dairy-free crema, cut the second lime into wedges. If making the crema, whisk 1/2 cup vegan mayo with the juice of 1/2 of the second lime and cut the remaining half into wedges. Fill the tortillas with the fish, slaw, and crema. Serve with the lime wedges. Four servings, two tacos each.', '["corn tortillas","dairy-free crema","lime"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_crispy-skillet-chicken-sandwiches_v1', 1, 'Pound and season', 'Butterfly the boneless skinless chicken breast into 4 pieces and pound each to about 1/4 inch. Pat dry. Season both sides with 3/4 tsp of the kosher salt, the black pepper, and the garlic powder.', '["boneless-skinless-chicken-breast","kosher-salt","black-pepper","garlic-powder"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_crispy-skillet-chicken-sandwiches_v1', 2, 'Mix the sauce', 'Stir the mayonnaise, dijon mustard, the zest and juice of the lemon, the fresh parsley, the garlic, and the remaining 1/4 tsp kosher salt. The mayonnaise is store-bought. This lemon-dijon mayonnaise is the only sauce. Use a dairy-free mayonnaise or the dairy-free label does not hold.', '["mayonnaise","dijon-mustard","lemon","fresh-parsley","garlic","kosher-salt"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_crispy-skillet-chicken-sandwiches_v1', 3, 'Dredge', 'Beat the eggs in a shallow bowl. Spread the all-purpose flour on a plate. Dip each piece in flour, then in egg, and set them on a clean plate. Let the excess egg drip off.', '["eggs","all-purpose-flour","boneless-skinless-chicken-breast"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_crispy-skillet-chicken-sandwiches_v1', 4, 'Sear', 'Heat a 12-inch skillet over medium-high. Add 2 tbsp of the canola oil. When it shimmers, add 2 pieces. Cook about 2 1/2 to 3 minutes per side, until the crust is deep golden and the center is 165°F. Repeat with the remaining 2 tbsp canola oil and the remaining pieces. If the crust darkens before 165°F, lower the heat to medium for the last minute. Do not crowd the pan.', '["canola-oil","boneless-skinless-chicken-breast"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_crispy-skillet-chicken-sandwiches_v1', 5, 'Toast the rolls', 'Wipe out loose browned bits if they will scorch. Toast the sandwich rolls, cut side down, in the skillet over medium heat for about 45 to 60 seconds.', '["sandwich-rolls"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_crispy-skillet-chicken-sandwiches_v1', 6, 'Assemble', 'Spread the lemon-dijon mayonnaise on the rolls. Add romaine lettuce, tomato, and a chicken cutlet. Serve right away. No fries and no pickles are part of this recipe.', '["mayonnaise","romaine-lettuce","tomato","boneless-skinless-chicken-breast","sandwich-rolls"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_ethiopian-beef-tibs_v1', 1, 'Cube and season the beef', 'Pat the beef dry. Cut into 3/4-inch cubes. Toss with 3/4 tsp kosher salt, black pepper, and 1 tbsp of the berbere. Rest 10 minutes at room temperature while you slice the onions and mince garlic and ginger. Dice the tomato. Chop the cilantro. Juice the lime. Confirm berbere is an Ethiopian blend, not plain chili powder.', '["beef-sirloin","kosher-salt","black-pepper","berbere","yellow-onion","garlic","fresh-ginger","tomato","fresh-cilantro","lime"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_ethiopian-beef-tibs_v1', 2, 'Sear the beef', 'Heat 2 tbsp of the neutral oil in a 12-inch skillet over medium-high until shimmering. Add the beef in a single layer (two batches if needed). Sear undisturbed until deeply browned on the first side, about 2 to 3 minutes. Toss and sear until browned on most sides but still pink inside, about 2 minutes more. Transfer beef to a plate. Do not cook through yet.', '["neutral-oil","beef-sirloin"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_ethiopian-beef-tibs_v1', 3, 'Cook the onion berbere base', 'Add the remaining 1 tbsp oil to the same skillet over medium heat. Add the sliced onions and 1/2 tsp kosher salt. Cook, stirring, until onions soften and pick up browned bits, about 6 to 8 minutes. Add garlic, ginger, remaining 1 tbsp berbere, smoked paprika, and optional cardamom. Cook until fragrant and brick-red, about 1 minute. Stir in the diced tomato. Cook until the tomato softens into the onions, about 2 to 3 minutes.', '["neutral-oil","yellow-onion","kosher-salt","garlic","fresh-ginger","berbere","smoked-paprika","ground-cardamom","tomato"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_ethiopian-beef-tibs_v1', 4, 'Finish tibs and plate', 'Return the seared beef and any plate juices to the skillet. Toss over medium-high heat until the beef is coated and cooked to medium (about 135–140 F for cubes), about 2 to 3 minutes. Do not stew into a long braise — tibs stay skillet-quick. Off heat, stir in lime juice and cilantro. Serve over cooked rice or sautéed greens. Injera on the side is optional if you have it; it is not required. No yogurt sauce. No nuts. kitchen_tested is false.', '["beef-sirloin","lime","fresh-cilantro","cooked-rice-or-greens"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_garlic-tomato-mussels_v1', 1, 'Clean the mussels', 'Rinse the mussels under cold water and scrub the shells. Pull off any beards. Discard cracked shells, any mussel that smells off, and any mussel that stays open after a firm tap. Do not add a long salt soak; it is not part of this timing.', '["mussels"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_garlic-tomato-mussels_v1', 2, 'Prep the bread and aromatics', 'Slice the crusty bread into 8 pieces and brush the slices with 1 tbsp of the olive oil. Dice the onion, slice the garlic, and chop the fresh parsley.', '["crusty-bread","olive-oil","onion","garlic","fresh-parsley"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_garlic-tomato-mussels_v1', 3, 'Start the broth', 'Warm the remaining 2 tbsp olive oil in a wide 8-quart pot over medium heat. Cook the onion for 3 minutes, until softened. Add the garlic and red pepper flakes and cook 1 minute. Do not let the garlic brown.', '["olive-oil","onion","garlic","red-pepper-flakes"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_garlic-tomato-mussels_v1', 4, 'Simmer', 'Add the crushed tomatoes, dry white wine, kosher salt, and black pepper. Simmer 4 minutes so the wine cooks off its raw edge and the tomatoes thicken slightly.', '["crushed-tomatoes","dry-white-wine","kosher-salt","black-pepper"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_garlic-tomato-mussels_v1', 5, 'Steam the mussels', 'Raise the heat to medium-high. Add the mussels, cover the pot, and cook 4 to 6 minutes, until the shells open. Shake the pot once halfway. Discard any mussel that is still closed. Do not cook them longer or they turn rubbery.', '["mussels"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_garlic-tomato-mussels_v1', 6, 'Toast the bread', 'While the mussels steam, toast the oiled crusty bread in a skillet or grill pan over medium-high, about 1 to 2 minutes per side, until the edges char. This is a skillet char, not a separate grilled meal.', '["crusty-bread"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_garlic-tomato-mussels_v1', 7, 'Finish', 'Take the pot off the heat. Squeeze in the juice of half the lemon and toss in the fresh parsley. Serve the mussels in their broth with the remaining lemon as wedges and the toasted bread. There is no pasta and no cheese.', '["lemon","fresh-parsley","mussels","crusty-bread"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_ginger-glazed-tempeh-plate_v1', 1, 'Prep tempeh, glaze, and vegetables', 'Slice the tempeh into 1/2-inch slabs. Optional but helpful: steam the slabs 8 minutes to mellow bitterness, then pat dry — if you steam, that time is inside prep. Whisk the tamari, maple syrup, grated ginger, minced garlic, rice vinegar, and 2 tbsp water into a glaze. Trim the broccolini. Slice the scallions. Confirm cooked rice is ready or start it now. HARD PEANUT CONTRACT: do not add peanut butter, peanut oil, or crushed peanuts.', '["tempeh","tamari","maple-syrup","fresh-ginger","garlic","rice-vinegar","water","broccolini","scallions","cooked-rice"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_ginger-glazed-tempeh-plate_v1', 2, 'Sear the tempeh', 'Heat 2 tbsp neutral oil in a 12-inch skillet over medium heat. Add tempeh slabs in a single layer. Cook until deep golden on the first side, about 3 to 4 minutes. Flip. Cook the second side until golden, about 3 minutes more. Transfer tempeh to a plate.', '["neutral-oil","tempeh"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_ginger-glazed-tempeh-plate_v1', 3, 'Blister the broccolini', 'Add the remaining 1 tbsp oil to the same skillet over medium-high heat. Add broccolini, kosher salt, and black pepper. Cook, tossing, until stems are tender-crisp and florets blister in spots, about 5 to 6 minutes. Transfer broccolini to the plate with tempeh (or a warm platter).', '["neutral-oil","broccolini","kosher-salt","black-pepper"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_ginger-glazed-tempeh-plate_v1', 4, 'Glaze and plate', 'Reduce heat to medium. Pour the glaze into the skillet. Simmer until slightly syrupy, about 1 to 2 minutes. Return tempeh to the pan and turn to coat, about 1 minute. Optional: drizzle 1 tsp toasted sesame oil off heat only if the household wants sesame — default is skip so sesame stays off the allergen array. Plate rice, broccolini, and glazed tempeh. Scatter scallions. No peanut garnish. kitchen_tested is false.', '["tamari","maple-syrup","fresh-ginger","garlic","tempeh","toasted-sesame-oil","cooked-rice","broccolini","scallions"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_ginger-scallion-fish-packets_v1', 1, 'Pack packets', 'Place fish and bok choy on foil; top with ginger, scallions, soy, and a splash of water.', '["white fish fillets","bok choy"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_ginger-scallion-fish-packets_v1', 2, 'Steam bake', 'Seal packets; bake at 400°F 18–20 min until fish flakes easily.', '["white fish fillets"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_ginger-scallion-fish-packets_v1', 3, 'Serve', 'Open carefully; serve with rice.', '[]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_ginger-scallion-fish-packets_v2', 1, 'Start the rice', 'Rinse the rice. Combine it with the 3 cups water in a saucepan. Bring to a boil, cover, and simmer 18 minutes, until the rice is tender and the water is absorbed. Rest covered, off heat, while the packets are opened. Do not salt the rice. Start this when the packets go into the oven. Do not add the 18 minutes on top of the bake.', '["long-grain white rice","water"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_ginger-scallion-fish-packets_v2', 2, 'Pack the packets', 'Heat the oven to 400 F. On each of 4 foil sheets, put 1 fish fillet and half a head of bok choy. Divide the ginger, scallions, soy sauce, and the 2 tbsp packet water across the four packets. Seal the foil.', '["white fish fillets","bok choy","ginger","scallions","soy sauce","water for packets"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_ginger-scallion-fish-packets_v2', 3, 'Bake', 'Bake at 400 F for 18 to 20 minutes, until the fish flakes easily and is opaque in the center and the bok choy is tender.', '["white fish fillets","bok choy"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_ginger-scallion-fish-packets_v2', 4, 'Serve', 'Open the foil carefully. Serve each packet with the rice. Do not add a sauce that was not in the packet.', '["long-grain white rice"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_gochujang-grilled-flank-steak_v1', 1, 'Mix the marinade', 'In a bowl, stir the gochujang, soy sauce, 1 tbsp of the rice vinegar, 3 tsp of the toasted sesame oil, brown sugar, garlic, fresh ginger, and black pepper into a thick paste. Mince 2 of the scallions and stir them in. This marinade cooks on the meat. Do not serve any of it raw.', '["gochujang","soy-sauce","rice-vinegar","toasted-sesame-oil","brown-sugar","garlic","fresh-ginger","black-pepper","scallions"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_gochujang-grilled-flank-steak_v1', 2, 'Marinate the steak', 'Pat the flank steak dry and coat both sides with all of the marinade. Leave it at room temperature for 15 minutes. Do not add kosher salt to the steak; the soy sauce is already salty.', '["flank-steak"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_gochujang-grilled-flank-steak_v1', 3, 'Make the salad', 'While the steak marinates, thinly slice the cucumber and slice the remaining 2 scallions. Toss them with the remaining 1 tbsp rice vinegar, the remaining 1 tsp toasted sesame oil, the kosher salt, and the sesame seeds.', '["cucumber","scallions","rice-vinegar","toasted-sesame-oil","kosher-salt","sesame-seeds"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_gochujang-grilled-flank-steak_v1', 4, 'Heat the grill', 'After the 15 minutes, heat a gas or charcoal grill for direct high heat, about 450–500°F. Give it about 10 minutes. When the grates are hot, brush them with the canola oil. This timed method does not overlap preheat with the marinade.', '["canola-oil"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_gochujang-grilled-flank-steak_v1', 5, 'Grill', 'Lay the flank steak on the oiled grates. Close the lid on a gas grill, or grill over direct coals with the vents open. Cook 4 to 5 minutes per side. It is done at 130–135°F in the thickest center for medium-rare. Do not press the steak. If the piece is thicker than 1 inch, add about 1 minute per side and trust the thermometer.', '["flank-steak"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_gochujang-grilled-flank-steak_v1', 6, 'Rest and slice', 'Move the flank steak to a board and rest it for 5 minutes. Slice it thin, against the grain: cut across the long muscle lines, not parallel to them. Discard any marinade left in the bowl.', '["flank-steak"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_gochujang-grilled-flank-steak_v1', 7, 'Plate', 'Serve the slices with the cucumber and scallions beside them. This plate has no rice and no extra sauce.', '["cucumber","scallions"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_greek-chicken-souvlaki_v1', 1, 'Marinate the chicken', 'In a bowl, whisk 3 tbsp olive oil, 3 tbsp of the lemon juice, the minced garlic, dried oregano, 1.25 tsp kosher salt, and black pepper. Add the chicken pieces and toss to coat. Marinate 20 minutes at room temperature (or up to 2 hours refrigerated). Meanwhile, soak 8 bamboo skewers in water if using wood.', '["olive-oil","lemon-juice","garlic","dried-oregano","kosher-salt","black-pepper","boneless-chicken-thighs"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_greek-chicken-souvlaki_v1', 2, 'Make the cucumber salad', 'In a serving bowl, combine the sliced cucumber, halved cherry tomatoes, sliced red onion, chopped dill, the remaining 1 tbsp lemon juice, the remaining 1 tbsp olive oil, and the remaining 1/4 tsp kosher salt. Toss. No yogurt, no feta, no olives required. Hold while the chicken cooks.', '["english-cucumber","cherry-tomatoes","red-onion","fresh-dill","lemon-juice","olive-oil","kosher-salt"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_greek-chicken-souvlaki_v1', 3, 'Thread the skewers', 'Thread the marinated chicken onto 8 skewers, packing pieces snugly but not crushed. Discard leftover marinade that touched raw chicken; do not brush it on after cooking.', '["boneless-chicken-thighs"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_greek-chicken-souvlaki_v1', 4, 'Grill or broil the souvlaki', 'Heat a grill or grill pan to medium-high, or set an oven broiler to high with a rack 6 inches from the element (broiler path: preheat 5 minutes overlaps skewer threading). Cook the skewers, turning every 2 to 3 minutes, until chicken is browned in spots and the thickest piece reads 165 F, about 10 to 12 minutes total. Do not serve pink chicken.', '["boneless-chicken-thighs"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_greek-chicken-souvlaki_v1', 5, 'Plate', 'Rest skewers 3 minutes. Serve 2 skewers per person with cucumber salad and lemon wedges. No pita, no tzatziki, no fries. kitchen_tested is false.', '["boneless-chicken-thighs","english-cucumber","lemon-wedges"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_grilled-peach-burrito-bowl_v1', 1, 'Grill peaches', 'Grill peach slices over medium-high heat 2 min per side until charred.', '["peaches"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_grilled-peach-burrito-bowl_v1', 2, 'Warm beans', 'Warm black beans with cumin and juice of ½ lime over medium heat 5 min.', '["black beans","cumin","lime"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_grilled-peach-burrito-bowl_v1', 3, 'Assemble bowls', 'Layer rice, beans, peaches, onion, cilantro.', '["lime rice"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_grilled-peach-burrito-bowl_v2', 1, 'Grill the peaches', 'Heat a grill to medium-high. Toss the peach slices with the neutral oil. Grill 2 minutes per side, until the edges are charred and the slices still hold their shape. This is a grill, not a stovetop. v1''s method list said only stovetop.', '["peaches","neutral oil"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_grilled-peach-burrito-bowl_v2', 2, 'Warm the beans', 'Warm the drained black beans with the cumin, the juice of 1/2 lime, and 1/4 tsp kosher salt over medium heat for 5 minutes, until heated through.', '["black beans","cumin","lime","kosher salt"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_grilled-peach-burrito-bowl_v2', 3, 'Season the rice', 'Toss the warm cooked long-grain rice with the zest of the lime, the juice of the remaining 1/2 lime, and the remaining 1/4 tsp kosher salt. v1 named the rice lime rice but never put lime on it, and it used only half of the lime in the beans.', '["cooked long-grain rice","lime","kosher salt"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_grilled-peach-burrito-bowl_v2', 4, 'Assemble the bowls', 'Layer rice, beans, grilled peaches, pickled red onion, and cilantro in bowls. The peaches stay on top, in slices. Four servings.', '["cooked long-grain rice","black beans","peaches","pickled red onion","cilantro"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_grilled-swordfish-olive-caper_v1', 1, 'Mix the relish', 'Chop the pitted green olives. Rinse and drain the capers. Mince the anchovy fillets and the garlic. Zest the lemon and squeeze in all of the juice. Chop the fresh parsley. Stir them with 3 tbsp of the olive oil, 1/4 tsp of the kosher salt, and the red pepper flakes. This olive-caper relish is the only sauce. It is not cooked, and it is not a marinade rubbed on the fish before the grill.', '["pitted-green-olives","capers","anchovy-fillets","garlic","lemon","fresh-parsley","olive-oil","kosher-salt","red-pepper-flakes"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_grilled-swordfish-olive-caper_v1', 2, 'Heat the grill', 'Heat a gas or charcoal grill for direct high heat, about 450-500 F, for about 10 minutes. Brush the grates with 1 tbsp of the olive oil. This clock does not overlap the preheat with the relish.', '["olive-oil"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_grilled-swordfish-olive-caper_v1', 3, 'Season', 'Pat the swordfish steak dry. Season both sides with 3/4 tsp of the kosher salt and the black pepper. Toss the fennel bulb wedges with 1 tbsp of the olive oil and the remaining 1/4 tsp kosher salt.', '["swordfish-steak","kosher-salt","black-pepper","fennel-bulb","olive-oil"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_grilled-swordfish-olive-caper_v1', 4, 'Grill the fennel', 'Lay the fennel bulb wedges on the oiled grates. Grill about 3 minutes per side, until the cut faces are browned and a knife meets slight resistance. Move them to a plate.', '["fennel-bulb"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_grilled-swordfish-olive-caper_v1', 5, 'Grill the swordfish', 'Lay the swordfish steak on the grates. Cook 4 minutes on the first side without moving it, then flip. Cook 3 to 4 minutes on the second side. Pull it at 130-135 F in the center. Do not press the fish. If a steak is thicker than 1 1/4 inches, add about 1 minute per side and trust the thermometer. For 145 F, add about 1 minute per side and expect a drier steak.', '["swordfish-steak"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_grilled-swordfish-olive-caper_v1', 6, 'Rest and plate', 'Rest the swordfish steak 3 minutes. Serve each steak with fennel bulb wedges and spoon the relish on the fish. No rice, no extra lemon wedge, and no second sauce.', '["swordfish-steak","fennel-bulb","pitted-green-olives","capers"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_harissa-roasted-carrots-feta_v1', 1, 'Roast', 'Coat carrots with harissa and oil; roast 30 min at 425°F.', '["carrots","harissa paste"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_harissa-roasted-carrots-feta_v1', 2, 'Finish', 'Top with feta and mint; serve over couscous.', '["feta","couscous"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_harissa-roasted-carrots-feta_v2', 1, 'Roast', 'Preheat the oven to 425 F. While it heats, coat the carrots with harissa and oil. Roast 30 minutes in the hot oven.', '["carrots","harissa paste","neutral oil"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_harissa-roasted-carrots-feta_v2', 2, 'Couscous', 'While the carrots finish, stir the couscous into 1 cup boiling water. Cover 5 minutes off the heat, then fluff.', '["couscous","water"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_harissa-roasted-carrots-feta_v2', 3, 'Finish', 'Top the carrots with feta and mint. Serve over the couscous.', '["feta","mint","couscous"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_herb-vegetable-pot-pie_v1', 1, 'Heat the oven, start the pastry thaw, and prep the vegetables', 'Heat the oven to 400 F with a rack in the center. Take the all-butter puff pastry sheet out of the freezer and leave it folded in its wrapper on the counter to thaw; it needs about 40 minutes and will be ready when the filling is done. Peel the carrots, parsnips, and Yukon Gold potatoes and cut each into 1/2-inch dice (quarter thick parsnip tops and cut out any woody core first). Dice the onion, thinly slice the celery, and mince the garlic. Strip the thyme leaves, finely mince the rosemary, and chop the parsley. Measure the butter, 1/3 cup flour, vegetable stock, cream, peas, salt, and pepper. About 20 minutes; this is the whole prep block.', '["all-butter-puff-pastry","carrots","parsnips","yukon-gold-potatoes","yellow-onion","celery","garlic","fresh-thyme","fresh-rosemary","fresh-parsley"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_herb-vegetable-pot-pie_v1', 2, 'Soften the aromatics and root vegetables in butter', 'Melt the 4 tbsp unsalted butter in a 5-quart Dutch oven or deep 12-inch skillet over medium heat. Add the onion and celery and cook, stirring, until soft and translucent, about 5 minutes. Add the carrots, parsnips, potatoes, and 1 tsp of the kosher salt. Cook, stirring often, until the vegetables are glossy and just beginning to soften at the edges, about 6 minutes. Add the garlic, thyme, and rosemary and cook 1 minute until fragrant. About 12 minutes.', '["unsalted-butter","yellow-onion","celery","carrots","parsnips","yukon-gold-potatoes","kosher-salt","garlic","fresh-thyme","fresh-rosemary"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_herb-vegetable-pot-pie_v1', 3, 'Build the herb gravy', 'Sprinkle the 1/3 cup all-purpose flour over the vegetables and stir constantly for 2 minutes so the flour coats everything and loses its raw smell. Pour in the vegetable stock slowly while stirring, scraping the bottom so no flour sticks, then stir in the heavy cream. Bring to a simmer, reduce to medium-low, and simmer, stirring often, until the gravy is thick enough to coat a spoon and a potato cube pierces with slight resistance, about 8 minutes (the vegetables finish in the oven). Take off the heat. Stir in the frozen peas, parsley, black pepper, and the remaining 1/4 tsp kosher salt. Pour the filling into an 8-inch square (2-quart) baking dish and set the dish on a rimmed sheet pan. This gravy is built from a butter-flour roux; it is not a canned cream soup. About 10 minutes.', '["all-purpose-flour","vegetable-stock","heavy-cream","frozen-peas","fresh-parsley","black-pepper","kosher-salt"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_herb-vegetable-pot-pie_v1', 4, 'Lid with puff pastry and egg wash', 'Lightly dust the counter and rolling pin with the 1 tbsp flour for dusting. Unfold the thawed puff pastry and roll it just enough to make a 10-inch square. Drape it over the filling, let the overhang fall onto the rim of the dish, and press it against the rim so it seals. Cut four 1-inch vents in the center. Beat the egg with the 1 tbsp water and brush a thin, even coat over the pastry top (skip the vents so they stay open). Discard the leftover egg wash. About 5 minutes.', '["flour-for-dusting","all-butter-puff-pastry","egg","water"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_herb-vegetable-pot-pie_v1', 5, 'Bake until the lid is deep golden', 'Bake the pot pie on the rimmed sheet pan in the 400 F oven until the pastry is puffed, flaky, and deep golden-brown and the gravy bubbles up through the vents, about 30 minutes. If the corners darken before the center is golden, lay a strip of foil loosely over the corners for the last few minutes. About 30 minutes.', '["all-butter-puff-pastry"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_herb-vegetable-pot-pie_v1', 6, 'Rest and serve', 'Let the pot pie rest 10 minutes so the gravy sets and does not run. Cut through the lid and spoon out portions with a shard of pastry on each. No chicken. No biscuit dump. No cheese on top. kitchen_tested is false. About 10 minutes.', '["all-butter-puff-pastry","carrots","parsnips","yukon-gold-potatoes","frozen-peas"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_herbed-polenta-tomato-stew_v1', 1, 'Cook polenta', 'Whisk polenta into simmering broth 20 min.', '["polenta","vegetable broth"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_herbed-polenta-tomato-stew_v1', 2, 'Stew tomatoes', 'Burst tomatoes with beans and rosemary 10 min.', '["cherry tomatoes","white beans"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_herbed-polenta-tomato-stew_v1', 3, 'Serve', 'Spoon stew over soft polenta.', '[]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_herbed-polenta-tomato-stew_v2', 1, 'Cook the polenta', 'Bring the vegetable broth and 3/4 tsp of the kosher salt to a simmer in a heavy saucepan. Whisk in the polenta. Cook over low heat, stirring often, 20 minutes, until the polenta is thick and soft and pulls from the side of the pan. This is stovetop. There is no sheet pan.', '["polenta","vegetable broth","kosher salt"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_herbed-polenta-tomato-stew_v2', 2, 'Stew the tomatoes', 'While the polenta cooks, warm the olive oil in a skillet over medium heat. Add the cherry tomatoes, fresh rosemary, the remaining 1/4 tsp kosher salt, and the black pepper. Cook until the tomatoes burst, about 8 minutes. Stir in the drained white beans and cook 2 minutes more, until the stew is spoonable rather than watery.', '["olive oil","cherry tomatoes","fresh rosemary","kosher salt","black pepper","white beans"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_herbed-polenta-tomato-stew_v2', 3, 'Serve', 'Spoon the stew over the soft polenta. Four servings. Do not add cheese or butter.', '[]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_jamaican-jerk-pork-chops_v1', 1, 'Make the jerk paste', 'In a blender or mini food processor, combine the scallions, thyme leaves, garlic, ginger, Scotch bonnet, ground allspice, cinnamon, nutmeg, brown sugar, tamari, 2 tbsp lime juice, 2 tbsp olive oil, 1 tsp kosher salt, and black pepper. Blend to a thick, spoonable paste, about 30 to 60 seconds, scraping once. Wear gloves when handling the Scotch bonnet.', '["scallions","fresh-thyme","garlic","fresh-ginger","scotch-bonnet","ground-allspice","ground-cinnamon","ground-nutmeg","brown-sugar","tamari","lime-juice","olive-oil","kosher-salt","black-pepper"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_jamaican-jerk-pork-chops_v1', 2, 'Coat the chops', 'Pat the pork chops dry. Rub all of the jerk paste over both sides of the 4 chops. Rest at room temperature 15 minutes while you make the slaw. Do not rinse the paste off.', '["bone-in-pork-chops"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_jamaican-jerk-pork-chops_v1', 3, 'Make the pineapple slaw', 'In a large bowl, toss the shredded green cabbage, diced pineapple, julienned red bell pepper, chopped cilantro, juice of 1 lime (about 2 tbsp), and the remaining 1/4 tsp kosher salt. Taste; the slaw should be bright and crunchy, not watery. Hold at room temperature while the chops cook.', '["green-cabbage","fresh-pineapple","red-bell-pepper","cilantro","lime-slaw","kosher-salt"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_jamaican-jerk-pork-chops_v1', 4, 'Sear the jerk chops', 'Heat the remaining 1 tbsp olive oil in a 12-inch skillet over medium heat. Add the chops in a single layer. Cook until the first side is deep brown with spice crust, about 5 to 6 minutes. Flip. Cook the second side until an instant-read thermometer in the thickest part away from bone reads 145 F, about 5 to 7 minutes more. If the paste darkens too fast, lower to medium-low. Do not char to bitter black.', '["olive-oil","bone-in-pork-chops"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_jamaican-jerk-pork-chops_v1', 5, 'Rest and plate', 'Transfer chops to a plate. Rest 5 minutes. Plate one chop per person with a mound of pineapple slaw beside it. Spoon any skillet juices over the pork. No second sauce. kitchen_tested is false.', '["bone-in-pork-chops","green-cabbage","fresh-pineapple"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_kimchi-fried-rice_v1', 1, 'Prep kimchi and rice', 'Confirm the kimchi label is plant/vegan with no fish sauce, shrimp paste, oysters, or anchovy. Roughly chop 2 cups kimchi; reserve 3 tbsp brine. Dice the onion. Mince the garlic. Slice scallions, keeping whites and greens separate. Break cold day-old rice into separate grains with wet fingers. Measure gochujang, soy sauce, toasted sesame oil, neutral oil, sugar, and sesame seeds. HARD CONTRACT: no egg, no bacon, no spam, no seafood kimchi.', '["plant-kimchi","kimchi-brine","yellow-onion","garlic","scallions","day-old-rice","gochujang","soy-sauce","toasted-sesame-oil","neutral-oil","sugar","toasted-sesame-seeds"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_kimchi-fried-rice_v1', 2, 'Sauté aromatics and kimchi', 'Heat the neutral oil and 1 tsp toasted sesame oil in a 12-inch skillet or wok over medium-high heat. Add onion and scallion whites. Cook, stirring, until onion softens, about 2 to 3 minutes. Add garlic; cook 30 seconds. Add chopped plant kimchi. Cook until edges look slightly jammy and the pan smells sharp and spicy, about 3 to 4 minutes. Stir in gochujang, kimchi brine, soy sauce, and sugar until the paste loosens into the kimchi.', '["neutral-oil","toasted-sesame-oil","yellow-onion","scallions","garlic","plant-kimchi","gochujang","kimchi-brine","soy-sauce","sugar"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_kimchi-fried-rice_v1', 3, 'Fry the rice', 'Add the cold rice. Press and fold to coat every grain in the red kimchi mixture. Spread into a thin layer. Let sit undisturbed 1 to 2 minutes so grains toast, then fold again. Repeat until rice is hot, stained red, and lightly toasted in spots, about 5 to 7 minutes total. Do not scramble an egg into the pan. Do not add bacon.', '["day-old-rice","plant-kimchi"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_kimchi-fried-rice_v1', 4, 'Finish and serve', 'Off heat, stir in the remaining 1 tsp toasted sesame oil and most of the scallion greens. Taste; add optional salt only if soy and kimchi have not already seasoned it. Serve in bowls. Scatter sesame seeds and remaining scallion greens. No fried egg on top. No bacon bits. kitchen_tested is false.', '["toasted-sesame-oil","scallions","toasted-sesame-seeds","kosher-salt","day-old-rice"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_korean-soft-tofu-stew_v1', 1, 'Prep', 'Drain the soft tofu and cut it into large spoonable chunks; leave them on a plate. Roughly chop the plant kimchi. Dice the yellow onion. Halve and slice the zucchini. Remove shiitake stems and slice the caps. Mince the garlic and fresh ginger. Thinly slice the scallions. Measure the gochugaru, gochujang, soy sauce, toasted sesame oil, neutral oil, vegetable stock, water, sugar, kosher salt, and black pepper. Confirm the kimchi label is plant/vegan with no fish sauce or shrimp. Do not crack any eggs; this stew has no egg garnish.', '["soft-tofu","plant-kimchi","yellow-onion","zucchini","shiitake-mushrooms","garlic","fresh-ginger","scallions","gochugaru","gochujang","soy-sauce","toasted-sesame-oil","neutral-oil","vegetable-stock","water","sugar","kosher-salt","black-pepper"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_korean-soft-tofu-stew_v1', 2, 'Start the aromatics', 'Heat the neutral oil and 1 tsp of the toasted sesame oil in a 3-to-4-quart pot or deep skillet over medium heat. Add the yellow onion and 1/4 tsp of the kosher salt. Cook, stirring, until the onion softens, about 4 minutes. Add the garlic, fresh ginger, and shiitake mushrooms. Cook until the mushrooms soften and smell fragrant, about 3 minutes. Do not brown hard.', '["neutral-oil","toasted-sesame-oil","yellow-onion","kosher-salt","garlic","fresh-ginger","shiitake-mushrooms"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_korean-soft-tofu-stew_v1', 3, 'Bloom the chili paste and flakes', 'Stir in the gochugaru and gochujang. Cook 1 minute, stirring so the paste coats the vegetables and darkens slightly. These are pantry chili products, not a bottled sundubu concentrate and not a seafood stew base.', '["gochugaru","gochujang"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_korean-soft-tofu-stew_v1', 4, 'Build the broth with plant kimchi', 'Add the plant kimchi, zucchini, vegetable stock, water, soy sauce, sugar, black pepper, and the remaining kosher salt only if needed after tasting later. Bring to a lively simmer over medium-high heat, then reduce to medium. Simmer uncovered about 8 minutes, until the zucchini is tender-crisp and the broth tastes spicy, sour, and savory. Do not add fish sauce, shrimp, clams, pork, or beef.', '["plant-kimchi","zucchini","vegetable-stock","water","soy-sauce","sugar","black-pepper","kosher-salt"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_korean-soft-tofu-stew_v1', 5, 'Add the soft tofu', 'Slide the soft tofu chunks into the pot. Spoon hot broth over them. Simmer gently, without vigorous boiling that breaks the tofu, about 5 minutes, until the tofu is hot through. Taste the broth. Add the remaining salt only if the soy sauce and kimchi have not already seasoned it enough.', '["soft-tofu","kosher-salt"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_korean-soft-tofu-stew_v1', 6, 'Finish', 'Take the pot off the heat. Stir in the remaining 1 tsp toasted sesame oil. Scatter the scallions over the top. Serve in bowls as a stew: soft tofu, kimchi, zucchini, mushrooms, and spicy broth. No egg on top. No rice is required by this recipe (rice on the side is outside the package). kitchen_tested is false.', '["toasted-sesame-oil","scallions","soft-tofu","plant-kimchi"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_lemon-garlic-shrimp-pasta_v1', 1, 'Cook pasta', 'Boil linguine; reserve water.', '["linguine"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_lemon-garlic-shrimp-pasta_v1', 2, 'Sauté shrimp', 'Sear shrimp with garlic in oil 2 min per side until pink.', '["large shrimp","garlic"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_lemon-garlic-shrimp-pasta_v1', 3, 'Finish', 'Toss pasta, shrimp, lemon zest/juice, parsley, and splash of pasta water.', '["lemon","parsley"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_lemon-garlic-shrimp-pasta_v2', 1, 'Cook pasta', 'Boil linguine; reserve water.', '["linguine"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_lemon-garlic-shrimp-pasta_v2', 2, 'Sauté shrimp', 'Sear shrimp with garlic in oil 2 min per side until pink.', '["large shrimp","garlic"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_lemon-garlic-shrimp-pasta_v2', 3, 'Finish', 'Toss pasta, shrimp, lemon zest/juice, parsley, and splash of pasta water.', '["lemon","parsley"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_lemon-pea-risotto_v1', 1, 'Heat the stock and prep', 'Bring the vegetable stock to a bare simmer in a saucepan and keep it hot over low heat for the whole cook. Finely dice the shallot. Mince the garlic. Finely grate the vegetarian Parmesan. Zest and juice the lemon. Chop the parsley. Measure the Arborio rice, frozen peas, wine, butter, olive oil, salt, and pepper. Do not rinse the rice.', '["vegetable-stock","shallot","garlic","vegetarian-parmesan","lemon-zest","lemon-juice","fresh-parsley","arborio-rice","frozen-peas","dry-white-wine","unsalted-butter","olive-oil","kosher-salt","black-pepper"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_lemon-pea-risotto_v1', 2, 'Soft the shallot and toast the rice', 'In a wide heavy pot or deep skillet, melt 1 tbsp of the unsalted butter with the olive oil over medium heat. Add the shallot and 1/4 tsp of the kosher salt. Cook until soft, about 3 minutes, without browning. Add the garlic and stir 30 seconds. Add the Arborio rice and stir until the edges look translucent, about 2 minutes. This toast is part of the risotto method, not a pilaf rinse.', '["unsalted-butter","olive-oil","shallot","kosher-salt","garlic","arborio-rice"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_lemon-pea-risotto_v1', 3, 'Deglaze with wine', 'Pour in the dry white wine. Stir until it is mostly absorbed, about 2 minutes. Do not add cream, milk, or cashew cream at any point; dairy finish is butter and Parmesan only.', '["dry-white-wine"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_lemon-pea-risotto_v1', 4, 'Ladle in hot stock', 'Add one ladle of hot vegetable stock (about 3/4 cup). Stir often until the liquid is mostly absorbed. Continue adding stock one ladle at a time, stirring often, for about 18 to 20 minutes total ladle time. The rice should be tender with a slight bite (al dente) and the pot should look creamy from the rice starch, not soupy and not dry/stuck. You may not need every last drop of the 5 cups; stop when the texture is right. kitchen_tested is false: 18 to 20 minutes is the expected agitation window.', '["vegetable-stock","arborio-rice"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_lemon-pea-risotto_v1', 5, 'Finish with peas, lemon, butter, and Parmesan', 'Stir in the frozen peas and cook 2 minutes until hot and bright green. Take the pot off the heat. Stir in the remaining 2 tbsp unsalted butter, the grated vegetarian Parmesan, the lemon zest, the lemon juice, the black pepper, and enough of the remaining kosher salt to taste. Fold in the parsley. The risotto should slowly spread on a plate, not stand in a stiff mound and not pour like soup. Serve immediately. No grilled chicken on top. No cream splash beyond the butter and cheese already listed.', '["frozen-peas","unsalted-butter","vegetarian-parmesan","lemon-zest","lemon-juice","black-pepper","kosher-salt","fresh-parsley"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_lentil-stuffed-cabbage_v1', 1, 'Blanch the cabbage', 'Bring a large pot of tap water to a boil with 1 tsp of the kosher salt. This blanch pot is not the measured water ingredient; that measured water is only for the lentils and the rice. The teaspoon of kosher salt is drained away and is not eaten. Do not drop it below 1 tsp when scaling. Core the green cabbage, lower the head in, and boil about 8 minutes, until 8 large outer leaves peel off without tearing. Rinse the leaves in cold water, pat them dry, and shave the thick part of each rib flat. Chop the leftover inner head. You need 8 leaves, not 12.', '["green-cabbage","kosher-salt"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_lentil-stuffed-cabbage_v1', 2, 'Simmer the lentils', 'Rinse the brown lentils. Simmer them in 4 cups of the water for 18 minutes, until tender with a bite in the center. If they are mush now, the rolls split later. Drain, and reserve 1/2 cup of that cooking water for the sauce. Discard the rest of the lentil water.', '["brown-lentils","water"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_lentil-stuffed-cabbage_v1', 3, 'Parcook the rice', 'In a separate pot, simmer the long-grain white rice in the remaining 2 cups of water for 8 minutes. It should be half-cooked, with a white core. Drain and discard that water. The rice finishes in the oven.', '["long-grain-white-rice","water"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_lentil-stuffed-cabbage_v1', 4, 'Mix the filling', 'Heat a skillet over medium. Add 1 tbsp of the olive oil and 1 diced yellow onion. Cook 5 minutes. Add 2 cloves of the garlic, the sweet paprika, 1.5 tsp of the kosher salt, and the black pepper. Stir 1 minute. Take the pan off the heat. Stir in the brown lentils, the long-grain white rice, and 2 tbsp of the fresh parsley. The filling should be moist, not soupy. If it is wet enough to pour, the rolls will burst.', '["olive-oil","yellow-onion","garlic","sweet-paprika","kosher-salt","black-pepper","brown-lentils","long-grain-white-rice","fresh-parsley"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_lentil-stuffed-cabbage_v1', 5, 'Make the sauce', 'In a saucepan over medium, heat the remaining 2 tbsp olive oil. Add the second diced yellow onion and cook 6 minutes. Add the remaining 2 cloves of garlic, the crushed tomatoes, the reserved 1/2 cup lentil water, the red wine vinegar, the brown sugar, the remaining 1 tsp kosher salt, and the chopped inner green cabbage. Simmer 10 minutes. The sauce should pour. If it is a paste, do not add new water; you have lost the reserved lentil water and this batch is off the recipe.', '["olive-oil","yellow-onion","garlic","crushed-tomatoes","water","red-wine-vinegar","brown-sugar","kosher-salt","green-cabbage"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_lentil-stuffed-cabbage_v1', 6, 'Roll', 'Heat the oven to 375 F now so it reaches temperature while you roll. Lay one green cabbage leaf flat. Spoon about 1/2 cup of filling on the rib end. Fold the sides in and roll it closed. Repeat for all 8 leaves. Pack them seam side down in a baking dish. Pour the sauce over them, including the crushed tomatoes. Cover. The oven preheat overlaps this rolling; do not add a separate cold-start wait after the tray is packed.', '["green-cabbage","brown-lentils","long-grain-white-rice","crushed-tomatoes"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_lentil-stuffed-cabbage_v1', 7, 'Bake', 'When the oven is at 375 F, bake 40 minutes covered, then 10 minutes uncovered, until a green cabbage leaf edge shows browned spots and the center of a roll is hot and steaming. The published cook clock stays sequential for stove and bake heat only: blanch 8 + lentils 18 + rice 8 + filling about 6 + sauce about 16 + bake 50 = about 106 minutes. Oven preheat is started in the roll step and is not a second cold start here. No sour cream, no cheese, and no bread.', '["green-cabbage"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_lentil-stuffed-cabbage_v1', 8, 'Serve', 'Serve two rolls per person with sauce. Sprinkle the remaining 1 tbsp fresh parsley. Do not add a dairy finish.', '["fresh-parsley"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_maple-mustard-glazed-salmon_v1', 1, 'Glaze', 'Mix mustard and maple; brush salmon and asparagus.', '["salmon fillets","Dijon mustard"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_maple-mustard-glazed-salmon_v1', 2, 'Roast', 'Roast at 400°F 12–15 min until salmon is opaque at center and asparagus is tender.', '["salmon fillets","asparagus"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_maple-mustard-glazed-salmon_v2', 1, 'Glaze', 'Heat the oven to 400 F. Mix the Dijon and the maple syrup. Brush it on the salmon and the asparagus. No oil is listed, and none is added.', '["Dijon mustard","maple syrup","salmon fillets","asparagus"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_maple-mustard-glazed-salmon_v2', 2, 'Roast', 'Roast on a sheet pan at 400 F for 12 to 15 minutes, until the salmon is opaque at the center and the asparagus is tender. Opaque at the center means cooked through, not rare.', '["salmon fillets","asparagus"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_miso-ginger-salmon_v1', 1, 'Marinate', 'Whisk miso, ginger, vinegar, sesame oil, and 1 tbsp water. Coat salmon and rest 15 min (or up to 30 in fridge).', '["salmon fillets","white miso","fresh ginger"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_miso-ginger-salmon_v1', 2, 'Cook salmon', 'Cook skin-side down on medium-high oiled skillet or griddle 4–5 min, flip, cook 3–4 min until just opaque in center.', '["salmon fillets"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_miso-ginger-salmon_v1', 3, 'Serve', 'Top with green onions and serve over rice with extra lime if desired.', '["green onions","steamed rice"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_miso-ginger-salmon_v2', 1, 'Marinate', 'Whisk the white miso, ginger, rice vinegar, sesame oil, and 1 tbsp water. Coat the skin-on salmon and rest 15 minutes. A longer fridge rest, up to 30 minutes, is optional and is not part of this 35-minute clock. The 15-minute rest is the bulk of the 20-minute prep.', '["salmon fillets","white miso","fresh ginger","rice vinegar","sesame oil","water"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_miso-ginger-salmon_v2', 2, 'Cook the salmon', 'Heat 1 tsp neutral oil in a skillet over medium-high. Cook the salmon skin-side down 4–5 minutes, flip, and cook 3–4 minutes more. Pull when the center is just opaque, about 145°F if checked.', '["salmon fillets","neutral oil"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_miso-ginger-salmon_v2', 3, 'Serve', 'Top with the green onions and serve over the steamed rice. There is no lime in this dish.', '["green onions","steamed rice"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_moroccan-chickpea-skillet_v1', 1, 'Spice chickpeas', 'Sauté spices in oil over medium heat 1 min; add chickpeas and splash of water; cook 5 min until glossy.', '["chickpeas","ras el hanout","neutral oil"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_moroccan-chickpea-skillet_v1', 2, 'Finish', 'Stir in preserved lemon and spinach.', '["spinach","preserved lemon"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_moroccan-chickpea-skillet_v1', 3, 'Serve', 'Serve over couscous.', '["couscous"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_moroccan-chickpea-skillet_v2', 1, 'Steam the couscous', 'Put the dry couscous and the kosher salt in a bowl. Pour over 1 1/2 cups boiling water. Cover and let stand 5 minutes. Fluff with a fork. This is wheat couscous for all 4 servings. v1 said only for serving.', '["couscous","water","kosher salt"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_moroccan-chickpea-skillet_v2', 2, 'Spice the chickpeas', 'Warm the neutral oil in a skillet over medium heat. Stir in the ras el hanout and cook 1 minute. Add the drained chickpeas and 1/4 cup water. Cook 5 minutes, until the chickpeas are glossy and the water is mostly gone.', '["neutral oil","ras el hanout","chickpeas","water"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_moroccan-chickpea-skillet_v2', 3, 'Finish', 'Stir in the preserved-lemon rind and the spinach. Cook 1-2 minutes, until the spinach is just wilted and the skillet is not soupy. Do not add more salt.', '["preserved lemon","spinach"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_moroccan-chickpea-skillet_v2', 4, 'Serve', 'Serve the skillet over the couscous. Four servings.', '["couscous"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_mushroom-walnut-bolognese_v1', 1, 'Brown mushrooms', 'Cook mushrooms and walnuts until deeply browned.', '["cremini mushrooms","walnuts"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_mushroom-walnut-bolognese_v1', 2, 'Simmer sauce', 'Add garlic, tomatoes; simmer 20 min.', '["crushed tomatoes"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_mushroom-walnut-bolognese_v1', 3, 'Toss pasta', 'Serve sauce over spaghetti.', '["spaghetti"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_mushroom-walnut-bolognese_v2', 1, 'Brown', 'Cook the mushrooms and walnuts in the olive oil until deeply browned, in batches if the pan is crowded.', '["cremini mushrooms","walnuts","olive oil"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_mushroom-walnut-bolognese_v2', 2, 'Simmer sauce', 'Add the garlic and tomatoes. Simmer 20 minutes. While that simmers, boil the spaghetti until tender and reserve ½ cup pasta water, so the boil shares the simmer instead of a separate block. The 30-minute cook is the browning plus this simmer. Season with the salt and pepper.', '["garlic","crushed tomatoes","kosher salt","black pepper","spaghetti"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_mushroom-walnut-bolognese_v2', 3, 'Toss pasta', 'Serve the sauce over the spaghetti, loosening it with pasta water if needed.', '["spaghetti"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_pan-fried-pork-dumplings_v1', 1, 'Salt the cabbage, prep aromatics, and make the dip', 'Toss the finely chopped napa cabbage with 1/2 tsp of the kosher salt in a bowl and let it stand 10 minutes to release water. Meanwhile, finely mince 3 of the scallions, thinly slice the green top of the fourth for the dip, grate the ginger, and mince the garlic. Stir together the dipping sauce in a small bowl: 3 tbsp of the soy sauce, the 3 tbsp unseasoned rice vinegar, 1 tsp of the toasted sesame oil, and the sliced scallion green. Gather the cabbage in a clean kitchen towel by handfuls and squeeze hard until no more liquid runs out; discard the liquid. About 10 minutes.', '["napa-cabbage","kosher-salt","scallions","fresh-ginger","garlic","soy-sauce","unseasoned-rice-vinegar","toasted-sesame-oil"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_pan-fried-pork-dumplings_v1', 2, 'Mix the pork filling', 'In a large bowl combine the ground pork, squeezed cabbage, minced scallions, ginger, garlic, the remaining 1 1/2 tbsp soy sauce, the remaining 2 tsp toasted sesame oil, sugar, white pepper, the remaining 1/2 tsp kosher salt, 1 tsp of the cornstarch, and 2 tbsp of the water. Stir firmly in one direction with chopsticks or a spatula for about 1 minute until the filling turns sticky and holds together. About 4 minutes.', '["ground-pork","napa-cabbage","scallions","fresh-ginger","garlic","soy-sauce","toasted-sesame-oil","sugar","white-pepper","kosher-salt","cornstarch","water"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_pan-fried-pork-dumplings_v1', 3, 'Fill and pleat the dumplings', 'Dust a sheet pan with the remaining 2 tsp cornstarch. Pour about 1/4 cup of the water into a small bowl. Keep the wrappers under a damp towel. Hold a wrapper in your palm, place a level 1 tbsp of filling in the center, and wet the outer edge halfway around with a fingertip of water. Fold into a half-moon, pinch the top center closed, then make 3 or 4 small pleats on the front edge on each side, pressing each pleat against the flat back edge to seal. Set the dumpling on the tray seam up so it sits on a flat bottom. Repeat to make 32 dumplings, keeping finished ones covered. Honest home-cook folding pace is about 45 seconds each, so allow about 25 minutes. About 25 minutes.', '["round-dumpling-wrappers","ground-pork","cornstarch","water"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_pan-fried-pork-dumplings_v1', 4, 'Pan-fry and steam the first batch', 'Heat 1 1/2 tbsp of the neutral oil in a 12-inch nonstick skillet with a tight lid over medium-high heat for about 1 minute. Arrange 16 dumplings flat-side down in snug rings, just touching. Fry undisturbed until the bottoms are golden, about 2 minutes. Carefully pour in 1/2 cup of the water (it will sputter), cover immediately, and lower the heat to medium. Steam 7 minutes, until the wrappers turn translucent and the filling is firm and cooked through (160 F if checked). Uncover and cook about 2 minutes more until the water is gone and the bottoms re-crisp and release. Slide onto a platter crisp-side up. About 12 minutes.', '["neutral-oil","round-dumpling-wrappers","water"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_pan-fried-pork-dumplings_v1', 5, 'Cook the second batch', 'Wipe the skillet if any bits scorched. Repeat with the remaining 1 1/2 tbsp neutral oil, the remaining 16 dumplings, and the remaining 1/2 cup water: 1 minute preheat, 2 minutes fry, 7 minutes covered steam, 2 minutes uncovered re-crisp. About 12 minutes.', '["neutral-oil","round-dumpling-wrappers","water"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_pan-fried-pork-dumplings_v1', 6, 'Serve with the soy-vinegar dip', 'Serve the dumplings crisp-side up with the soy-vinegar dipping sauce on the side. Not deep-fried. Not boiled. No shrimp, no chicken. kitchen_tested is false.', '["round-dumpling-wrappers","soy-sauce","unseasoned-rice-vinegar","scallions"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_peanut-noodle-stir-fry_v1', 1, 'Cook noodles', 'Soak noodles in hot water 8–10 min until tender; drain.', '["rice noodles"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_peanut-noodle-stir-fry_v1', 2, 'Sauce', 'Whisk peanut butter, soy, juice of ½ lime, and 3 tbsp warm water until smooth.', '["peanut butter","soy sauce","lime"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_peanut-noodle-stir-fry_v1', 3, 'Stir-fry', 'Sear peppers and peas in oil over high heat 3–4 min; toss with noodles and sauce until coated.', '["bell pepper","snap peas","neutral oil"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_peanut-noodle-stir-fry_v2', 1, 'Cook noodles', 'Soak the noodles in hot water 8–10 minutes until tender, then drain.', '["rice noodles"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_peanut-noodle-stir-fry_v2', 2, 'Sauce', 'Whisk the peanut butter, soy sauce, juice of ½ lime, and 3 tbsp warm water until smooth.', '["peanut butter","soy sauce","lime","water"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_peanut-noodle-stir-fry_v2', 3, 'Stir-fry', 'Sear the peppers and snap peas in the oil over high heat 3–4 minutes. Toss with the noodles and sauce until coated.', '["bell pepper","snap peas","neutral oil","rice noodles"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_potato-leek-gratin_v1', 1, 'Slice and grate', 'Peel the Yukon Gold potatoes and slice them 1/8 inch thick. Hold the slices in cold water so they do not discolor. Trim the leeks to the white and pale green, halve them lengthwise, rinse out the grit, and slice them 1/4 inch thick. Grate the vegetarian Gruyère. Mince the garlic. Strip the fresh thyme leaves. This prep finishes before the oven is turned on.', '["yukon-gold-potatoes","leeks","vegetarian-gruyere","garlic","fresh-thyme"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_potato-leek-gratin_v1', 2, 'Heat the oven and soften the leeks', 'Heat the oven to 400 F. The preheat takes about 10 minutes, and those 10 minutes are inside the cook time. During that same 10 minutes, melt 1 tbsp of the unsalted butter in a skillet over medium heat. Add the leeks and 1/4 tsp of the kosher salt. Cook until soft, about 8 minutes. Do not let them go dark brown. The leek cooking is inside the preheat and is not a second block of time.', '["unsalted-butter","leeks","kosher-salt"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_potato-leek-gratin_v1', 3, 'Mix the cream-cheese custard', 'Whisk the heavy cream with 2 oz of the vegetarian Gruyère, the garlic, 1 tsp of the kosher salt, the black pepper, the ground nutmeg, and the fresh thyme. This cream-cheese custard is defined here from those ingredients. It is not a bottled sauce. There is no egg and no flour in it. The remaining 2 oz of cheese is for the top.', '["heavy-cream","vegetarian-gruyere","garlic","kosher-salt","black-pepper","ground-nutmeg","fresh-thyme"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_potato-leek-gratin_v1', 4, 'Layer the dish', 'Use the remaining 1 tbsp unsalted butter to grease a 2-quart baking dish. Drain the Yukon Gold potatoes and pat them dry. Layer the potatoes with the softened leeks, pouring the cream-cheese custard over the layers as you go. Press the slices down so the cream comes nearly to the top. Do not add milk, stock, or water that is not in the ingredient list. Scatter the remaining 2 oz vegetarian Gruyère over the top. Do not add breadcrumbs.', '["unsalted-butter","yukon-gold-potatoes","leeks","heavy-cream","vegetarian-gruyere"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_potato-leek-gratin_v1', 5, 'Bake and rest', 'Bake on the middle rack at 400 F for 40 minutes. A knife should meet little resistance in a center potato slice, the cream should be bubbling at the edges and look thickened, and the cheese on top should be browned in patches. If the top colors deeply before the 40 minutes are up, lay a loose piece of foil over the dish for the rest of that 40 minutes. Rest 5 minutes before serving. The 40-minute bake and the 5-minute rest come after the 10-minute preheat and are inside the cook time. There is no breadcrumb crust. kitchen_tested is false: 40 minutes is the expected bake for 1/8-inch slices, not a tested promise. If the center is still firm at 40 minutes, keep baking and check every 5 minutes; that extra time is not inside the 70-minute total.', '["yukon-gold-potatoes","heavy-cream","vegetarian-gruyere"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_roasted-butternut-farro-plate_v1', 1, 'Roast the squash', 'Heat the oven to 425 F. Seed the butternut squash and cut it into 1-inch wedges. Toss with 1 tbsp of the olive oil, 1 tsp of the kosher salt, and 1/4 tsp of the black pepper. Spread in one layer on a sheet pan. Roast 35 minutes, flipping at 20 minutes, until the edges are browned and a knife meets no resistance. There is no flour and no breading.', '["butternut-squash","olive-oil","kosher-salt","black-pepper"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_roasted-butternut-farro-plate_v1', 2, 'Simmer the farro', 'When the pan goes into the oven, rinse the farro and simmer it in the water with the bay leaf and 3/4 tsp of the kosher salt for 30 minutes, until the grains are tender and some have split. Drain. Discard the bay leaf. This 30 minutes sits inside the 35-minute roast and is not added on top of it. Use pearled farro. Whole farro will not finish in this water or this time. If the pot goes dry before 25 minutes, the pot was too wide; this recipe does not add a rescue splash.', '["farro","water","bay-leaf","kosher-salt"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_roasted-butternut-farro-plate_v1', 3, 'Mix the dressing', 'Whisk the remaining 4 tbsp olive oil with the zest and all of the juice of the lemon, the garlic, the dijon mustard, the fresh parsley, the remaining 1/4 tsp kosher salt, and the remaining 1/4 tsp black pepper until it looks lightly thickened. If it separates, whisk again. Do not add water, honey, or cheese.', '["olive-oil","lemon","garlic","dijon-mustard","fresh-parsley","kosher-salt","black-pepper"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_roasted-butternut-farro-plate_v1', 4, 'Plate', 'Use a dinner plate, not a bowl. Put the farro on one side and the butternut squash wedges on the other. Do not toss them together. Spoon the dressing across both. No cheese, no nuts, no seeds, and no bread.', '["farro","butternut-squash","lemon","fresh-parsley"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_roasted-cauliflower-shawarma-plate_v1', 1, 'Roast cauliflower', 'Toss cauliflower with oil and spices; roast at 425°F 25 min until charred at edges.', '["cauliflower florets","neutral oil","shawarma spice blend"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_roasted-cauliflower-shawarma-plate_v1', 2, 'Make sauce', 'Whisk tahini with juice of ½ lemon and water to drizzle.', '["tahini","lemon"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_roasted-cauliflower-shawarma-plate_v1', 3, 'Plate', 'Serve cauliflower with cucumber, sauce, and warm pita.', '["pita","cucumber"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_roasted-cauliflower-shawarma-plate_v2', 1, 'Roast the cauliflower', 'Preheat the oven to 425 F. While it heats, toss the florets with the oil and the shawarma spice and spread them in one layer on a sheet pan. Roast 25 minutes in the hot oven, until the edges are charred and a stem is tender.', '["cauliflower","neutral oil","shawarma spice blend"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_roasted-cauliflower-shawarma-plate_v2', 2, 'Make the sauce', 'Whisk the tahini with the juice of 1/2 lemon and the 3 tbsp water until it drizzles off the spoon. Do not add garlic. The remaining lemon half is not served.', '["tahini","lemon","water"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_roasted-cauliflower-shawarma-plate_v2', 3, 'Warm the pita and plate', 'Dice the cucumber. For the last 3 minutes of the roast, warm the pita wrapped in foil in the same oven. Serve the cauliflower, cucumber, sauce, and pita on a plate. Do not wrap it, do not put it in a bowl, and do not add feta, herbs, hummus, or tomato.', '["cucumber","pita","cauliflower"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_saag-paneer_v1', 1, 'Prep spinach and paneer', 'Bring a large pot of water to a boil. Add the baby spinach and cook just until collapsed, about 1 minute. Drain and rinse under cold water. Squeeze out excess water firmly. Chop the spinach roughly, or pulse a few times in a food processor to a coarse puree (not a baby-food slick). Cut the paneer into 3/4-inch cubes and pat dry. Dice the onion. Mince the garlic, ginger, and jalapeño. Measure the spices, cream, butter, oil, tomatoes, salt, cilantro, and lemon juice.', '["baby-spinach","paneer","yellow-onion","garlic","fresh-ginger","jalapeno","ground-cumin","ground-coriander","ground-turmeric","garam-masala","cayenne-pepper","heavy-cream","unsalted-butter","neutral-oil","canned-diced-tomatoes","kosher-salt","fresh-cilantro","lemon-juice","water"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_saag-paneer_v1', 2, 'Brown the paneer', 'Heat 2 tbsp of the neutral oil in a 12-inch skillet over medium-high heat. Add the paneer cubes and 1/4 tsp of the kosher salt. Cook, turning, until golden on several sides, about 5 to 6 minutes. Transfer the paneer to a plate. Do not add meat. Do not substitute tofu in this package and still call it saag paneer.', '["neutral-oil","paneer","kosher-salt"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_saag-paneer_v1', 3, 'Build the onion-spice base', 'Reduce heat to medium. Add the remaining 1 tbsp neutral oil. Add the yellow onion and cook until soft and lightly golden, about 6 minutes. Add the garlic, ginger, and jalapeño. Cook 1 minute. Stir in the ground cumin, ground coriander, ground turmeric, 1/2 tsp of the garam masala, and the optional cayenne. Stir 30 to 60 seconds until fragrant.', '["neutral-oil","yellow-onion","garlic","fresh-ginger","jalapeno","ground-cumin","ground-coriander","ground-turmeric","garam-masala","cayenne-pepper"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_saag-paneer_v1', 4, 'Simmer tomatoes and spinach', 'Add the canned diced tomatoes and 1 tsp of the kosher salt. Cook, stirring, until the tomatoes look jammy and most free liquid has cooked down, about 5 minutes. Stir in the chopped spinach and up to 1/2 cup water as needed so the saag is saucy but not watery. Simmer about 5 minutes. This spinach-tomato saag is made in the skillet, not a jarred spinach sauce.', '["canned-diced-tomatoes","kosher-salt","baby-spinach","water"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_saag-paneer_v1', 5, 'Return paneer and finish with dairy', 'Return the browned paneer to the skillet. Simmer 3 minutes so the cubes heat through. Stir in the heavy cream, unsalted butter, and the remaining 1/2 tsp garam masala. Warm through 1 minute without a hard boil. Take off the heat. Stir in the lemon juice and cilantro. Serve as a skillet saag with paneer cubes visible. No chicken. No lamb. kitchen_tested is false.', '["paneer","heavy-cream","unsalted-butter","garam-masala","lemon-juice","fresh-cilantro"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_sesame-soba-noodle-bowl_v1', 1, 'Cook noodles', 'Boil soba; rinse cold.', '["soba noodles"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_sesame-soba-noodle-bowl_v1', 2, 'Dress', 'Toss noodles with sesame oil, vinegar, soy, and vegetables.', '["sesame oil","rice vinegar","soy sauce","carrot"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_sesame-soba-noodle-bowl_v1', 3, 'Top', 'Top with edamame and sesame seeds.', '["edamame"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_sesame-soba-noodle-bowl_v2', 1, 'Cook the noodles', 'Boil the soba 4 to 5 minutes, until tender but not mushy. Drain and rinse under cold water until cool. This is not a 25-minute boil and it is not a broth soup.', '["soba noodles"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_sesame-soba-noodle-bowl_v2', 2, 'Dress', 'Toss the cooled noodles with the sesame oil, rice vinegar, soy sauce, and julienned carrot.', '["sesame oil","rice vinegar","soy sauce","carrot"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_sesame-soba-noodle-bowl_v2', 3, 'Top', 'Top with the edamame and the sesame seeds. Do not add lime, cilantro, peanut, or another vegetable.', '["edamame","sesame seeds"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_sheet-pan-lemon-herb-chicken_v1', 1, 'Season & arrange', 'Toss chicken, potatoes, beans with oil, lemon, oregano, salt, pepper on one pan.', '["chicken thighs","potatoes","neutral oil"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_sheet-pan-lemon-herb-chicken_v1', 2, 'Roast', 'Roast at 425°F 35–40 min until chicken hits 165°F.', '["chicken thighs"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_sheet-pan-lemon-herb-chicken_v1', 3, 'Rest', 'Rest 5 min; squeeze remaining lemon over top.', '["lemon"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_sheet-pan-lemon-herb-chicken_v2', 1, 'Season and arrange', 'Preheat the oven to 425 F. While it heats, toss the chicken and potatoes with the oil, half the lemon, oregano, salt, and pepper on one sheet pan. Leave the green beans off for now.', '["chicken thighs","potatoes","neutral oil","lemon","dried oregano","kosher salt","black pepper"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_sheet-pan-lemon-herb-chicken_v2', 2, 'Roast', 'Roast in that hot oven at 425°F until the chicken reaches 165°F, 35–40 minutes. Add the green beans for about the last 12 minutes.', '["chicken thighs","green beans"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_sheet-pan-lemon-herb-chicken_v2', 3, 'Rest', 'Rest 5 minutes, then squeeze the remaining lemon over the top.', '["lemon"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_sheet-pan-margherita-pizza_v1', 1, 'Heat the oven and oil the pan with the dough', 'Set a rack in the lower third of the oven and heat the oven to 475 F (it needs about 20 minutes and will be ready before the pizza goes in). Pour 2 tbsp of the extra-virgin olive oil onto a 13x18-inch rimmed half-sheet pan and spread it to the corners. Set the cold store-bought dough in the pan, turn it once to coat with oil, and press it into a rough rectangle with your fingertips. Cover loosely with a clean towel and let it rest 20 minutes so the gluten relaxes. About 5 minutes of work; the 20-minute rest begins now.', '["pizza-dough","extra-virgin-olive-oil"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_sheet-pan-margherita-pizza_v1', 2, 'Make the sauce and prep the mozzarella during the rest', 'Stir together the crushed tomatoes, grated garlic, 1 tbsp of the extra-virgin olive oil, and the 1/2 tsp kosher salt. This sauce is not cooked ahead; it reduces on the pizza. Drain the fresh mozzarella, tear it into 1-inch pieces, spread them on paper towels, and press more towels on top to blot surface water so the pizza does not puddle. Pick the basil leaves and tear any large ones. About 10 minutes, inside the dough rest.', '["crushed-tomatoes","garlic","extra-virgin-olive-oil","kosher-salt","fresh-mozzarella","fresh-basil"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_sheet-pan-margherita-pizza_v1', 3, 'Press the dough to the corners', 'When the dough has rested the full 20 minutes (about 10 minutes after the sauce is done), press it outward with oiled fingertips toward the corners and edges, dimpling as you go, about 3 minutes. It will spring back. Rest 5 minutes more, then press again until it fills the pan to the corners in an even layer, about 2 minutes. About 20 minutes including the remaining rest time.', '["pizza-dough"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_sheet-pan-margherita-pizza_v1', 4, 'Sauce and first bake', 'Spread the tomato sauce evenly over the dough, leaving a 1/2-inch border. Bake on the lower rack at 475 F until the edges are set and lightly golden and the underside is starting to brown, about 12 minutes. Baking the sauced crust first keeps the fresh mozzarella from weeping before the base sets. About 12 minutes.', '["crushed-tomatoes","pizza-dough"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_sheet-pan-margherita-pizza_v1', 5, 'Add mozzarella and finish the bake', 'Pull the pan out and scatter the blotted fresh mozzarella pieces evenly over the sauce. Return to the lower rack and bake until the cheese is melted, bubbling, and lightly spotted golden and the crust underneath is deep golden and crisp when you lift a corner with a spatula, about 9 minutes. About 9 minutes.', '["fresh-mozzarella","pizza-dough"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_sheet-pan-margherita-pizza_v1', 6, 'Rest, add basil, and cut', 'Let the pizza rest in the pan 3 minutes so the cheese sets. Scatter the fresh basil leaves over the top, then slide the pizza onto a board (or cut in the pan with a pizza wheel) and cut into 12 squares. No pepperoni, no prosciutto, no Parmesan shower. kitchen_tested is false. About 3 minutes.', '["fresh-basil","fresh-mozzarella","pizza-dough"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_skillet-shakshuka_v1', 1, 'Prep', 'Dice the yellow onion. Stem, seed, and slice the red bell pepper. Mince the garlic. Chop the fresh parsley. Measure the sweet paprika, ground cumin, ground coriander, sugar, kosher salt, and black pepper. Leave the eggs whole until the sauce can hold a well.', '["yellow-onion","red-bell-pepper","garlic","fresh-parsley","sweet-paprika","ground-cumin","ground-coriander","sugar","kosher-salt","black-pepper","eggs"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_skillet-shakshuka_v1', 2, 'Soften the onion and peppers', 'Heat the olive oil in a 12-inch skillet over medium heat. Add the yellow onion, the red bell pepper, and 1/4 tsp of the kosher salt. Cook, stirring, until the onion is soft and the pepper has slumped, about 8 minutes. Do not char them.', '["olive-oil","yellow-onion","red-bell-pepper","kosher-salt"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_skillet-shakshuka_v1', 3, 'Bloom the spices', 'Add the garlic, sweet paprika, ground cumin, and ground coriander. Stir for 1 minute, until fragrant. These are ground spices, not a jar of shakshuka sauce and not a paste.', '["garlic","sweet-paprika","ground-cumin","ground-coriander"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_skillet-shakshuka_v1', 4, 'Simmer the tomato-pepper sauce', 'Pour in the canned crushed tomatoes and the water. Add the sugar, 3/4 tsp of the kosher salt, and the black pepper. Stir. Simmer uncovered over medium heat until the sauce thickens enough that a spoon leaves a well, about 10 minutes. This tomato-pepper sauce is the only sauce, and it is made in this skillet. Do not add cheese, yogurt, butter, cream, or bread.', '["crushed-tomatoes","water","sugar","kosher-salt","black-pepper"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_skillet-shakshuka_v1', 5, 'Set the eggs', 'Make 8 wells in the sauce. Crack 1 egg into each well, 8 eggs total, 2 per serving. Sprinkle the remaining 1/4 tsp kosher salt over the eggs. Cover the skillet. Cook over medium-low for 6 to 8 minutes. The whites must be fully set, with no liquid white at the edge. The yolks stay soft and glossy. Do not flip the eggs. For firm yolks, cover about 2 minutes more. The written target is soft yolks. kitchen_tested is false.', '["eggs","kosher-salt"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_skillet-shakshuka_v1', 6, 'Finish in the skillet', 'Take the skillet off the heat. Scatter the fresh parsley over the sauce and eggs. Serve from the skillet. Each serving is 2 eggs with tomato-pepper sauce. No cheese, no yogurt, no bread, and no second sauce.', '["fresh-parsley","eggs","crushed-tomatoes"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_smoky-lentil-sweet-potato-stew_v1', 1, 'Simmer base', 'Simmer lentils, sweet potato, tomatoes, paprika, and broth 25 min.', '["red lentils","sweet potato"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_smoky-lentil-sweet-potato-stew_v1', 2, 'Mash slightly', 'Partially mash to thicken; season.', '["diced tomatoes"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_smoky-lentil-sweet-potato-stew_v1', 3, 'Serve', 'Serve with crusty bread if desired.', '[]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_smoky-lentil-sweet-potato-stew_v2', 1, 'Simmer', 'Put the rinsed red lentils, sweet potato cubes, diced tomatoes with their juice, smoked paprika, vegetable broth, kosher salt, and black pepper in a pot. Bring to a simmer, then simmer 25 minutes, until the sweet potato is tender and the lentils have broken down.', '["red lentils","sweet potato","diced tomatoes","smoked paprika","vegetable broth","kosher salt","black pepper"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_smoky-lentil-sweet-potato-stew_v2', 2, 'Mash slightly', 'Mash a portion of the stew against the side of the pot until it thickens. Leave some sweet potato cubes visible.', '["sweet potato","red lentils"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_smoky-lentil-sweet-potato-stew_v2', 3, 'Serve', 'Serve the stew as it is. Bread is not part of this dish.', '[]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_spanish-chorizo-pepper-rice_v1', 1, 'Prep the pan ingredients', 'Slice the Spanish chorizo into 1/4-inch coins. Dice the yellow onion. Cut the red and green bell peppers into 1/2-inch strips. Mince the garlic. Rinse the rice until the water runs clearer; drain well. Chop the parsley. Cut the lemon into wedges. Measure the smoked paprika, cumin, crushed tomatoes, stock, olive oil, kosher salt, and black pepper. Confirm the chorizo is cured Spanish-style pork sausage, not Mexican fresh chorizo and not a seafood sausage.', '["spanish-chorizo","yellow-onion","red-bell-pepper","green-bell-pepper","garlic","short-grain-rice","fresh-parsley","lemon","smoked-paprika","ground-cumin","crushed-tomatoes","vegetable-stock","olive-oil","kosher-salt","black-pepper"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_spanish-chorizo-pepper-rice_v1', 2, 'Brown the chorizo and blister the peppers', 'Heat the olive oil in a 12-inch deep skillet or wide sauté pan over medium heat. Add the chorizo coins in a single layer. Cook, turning once, until the edges brown and paprika-stained fat renders, about 4 to 5 minutes. Add the onion and both peppers with 1/2 tsp of the kosher salt. Cook, stirring occasionally, until the peppers blister at the edges and the onion softens, about 6 to 7 minutes. Do not add shrimp, mussels, or clams.', '["olive-oil","spanish-chorizo","yellow-onion","red-bell-pepper","green-bell-pepper","kosher-salt"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_spanish-chorizo-pepper-rice_v1', 3, 'Toast spices and rice', 'Stir in the garlic, smoked paprika, and cumin. Cook until fragrant, about 30 to 45 seconds. Add the rinsed drained rice. Stir to coat every grain in the red fat, about 1 minute. Pour in the crushed tomatoes and stock. Add the remaining 1/2 tsp kosher salt and the black pepper. Stir once to settle the rice in an even layer. Bring to a lively simmer over medium-high heat.', '["garlic","smoked-paprika","ground-cumin","short-grain-rice","crushed-tomatoes","vegetable-stock","kosher-salt","black-pepper"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_spanish-chorizo-pepper-rice_v1', 4, 'Absorb and rest', 'Reduce heat to low. Cover tightly. Cook undisturbed until the rice is tender and the liquid is absorbed, about 16 to 18 minutes. Remove from heat. Rest covered 5 minutes. Fluff with a fork. Taste; the rice should be seasoned by the chorizo fat, paprika, and tomatoes — add a pinch more salt only if needed. Scatter the parsley. Serve from the pan with lemon wedges. No paella socarrat chase required. No shellfish. kitchen_tested is false.', '["short-grain-rice","fresh-parsley","lemon","spanish-chorizo"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_spiced-lamb-meatballs_v1', 1, 'Mix the meatballs', 'In a large bowl, combine the ground lamb, beaten egg, panko, grated half onion, 3 cloves minced garlic, half the parsley (1/4 cup), all the mint, cumin, coriander, paprika, red pepper flakes, 1.25 tsp kosher salt, and black pepper. Mix with a fork or clean hands just until combined. Do not overwork. Shape into 16 meatballs, about 1.5 inches each.', '["ground-lamb","egg","panko","yellow-onion","garlic","fresh-parsley","fresh-mint","ground-cumin","ground-coriander","sweet-paprika","red-pepper-flakes","kosher-salt","black-pepper"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_spiced-lamb-meatballs_v1', 2, 'Brown the meatballs', 'Heat 2 tbsp olive oil in a 12-inch skillet over medium-high. Add the meatballs in a single layer, working in two batches if needed. Brown on two sides until a crust forms, about 2 to 3 minutes per side. They will not be cooked through. Transfer to a plate.', '["olive-oil","ground-lamb"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_spiced-lamb-meatballs_v1', 3, 'Build the tomato-herb sauce', 'Reduce heat to medium. Add the remaining 1 tbsp olive oil and the diced onion half. Cook until soft, about 4 minutes. Add the remaining 2 cloves minced garlic and the tomato paste. Stir 1 minute. Pour in the crushed tomatoes and water. Add the remaining 0.5 tsp kosher salt. Simmer 3 minutes, scraping browned bits.', '["olive-oil","yellow-onion","garlic","tomato-paste","crushed-tomatoes","water","kosher-salt"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_spiced-lamb-meatballs_v1', 4, 'Simmer meatballs in sauce', 'Nestle the browned meatballs into the sauce. Simmer uncovered over medium-low, turning once, until the centers read 160 F and the sauce has thickened slightly, about 12 to 14 minutes.', '["ground-lamb","crushed-tomatoes"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_spiced-lamb-meatballs_v1', 5, 'Finish with herbs', 'Take the skillet off the heat. Scatter the remaining 1/4 cup parsley over the meatballs and sauce. Serve from the skillet: 4 meatballs with sauce per person. No yogurt, no cheese, no pasta required. kitchen_tested is false.', '["fresh-parsley","ground-lamb","crushed-tomatoes"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_teriyaki-tofu-bowls_v1', 1, 'Bake tofu', 'Cube tofu, toss with half the teriyaki glaze, bake at 425°F 20 min until edges are golden and crisp.', '["extra-firm tofu","soy sauce"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_teriyaki-tofu-bowls_v1', 2, 'Steam broccoli', 'Steam or roast broccoli until tender-crisp.', '["broccoli florets"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_teriyaki-tofu-bowls_v1', 3, 'Assemble bowls', 'Serve rice, tofu, broccoli, remaining glaze, sesame.', '["jasmine rice","sesame seeds"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_teriyaki-tofu-bowls_v2', 1, 'Heat the oven and mix the glaze', 'Heat the oven to 425°F at the start of prep so the preheat overlaps the press. Press the tofu 15 minutes, cube it, and pat it dry. Whisk the soy sauce, maple syrup, and rice vinegar. That is the teriyaki glaze. Divide it in half. Stir the cornstarch into the reserved half. Toss the tofu with the oil and the other half.', '["extra-firm tofu","soy sauce","maple syrup","rice vinegar","cornstarch","neutral oil"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_teriyaki-tofu-bowls_v2', 2, 'Bake the tofu', 'Spread the tofu in one layer on a sheet pan. Bake at 425°F for 20 minutes, turning once, until the edges are browned and the exterior is set.', '["extra-firm tofu"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_teriyaki-tofu-bowls_v2', 3, 'Steam the broccoli', 'While the tofu bakes, steam the broccoli with 1/4 tsp kosher salt until tender-crisp, about 4 minutes. Do not roast it.', '["broccoli florets","kosher salt"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_teriyaki-tofu-bowls_v2', 4, 'Thicken the reserved glaze', 'Simmer the reserved cornstarch half for about 1 minute, until it coats a spoon.', '["soy sauce","maple syrup","rice vinegar","cornstarch"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_teriyaki-tofu-bowls_v2', 5, 'Assemble the bowls', 'Cook the jasmine rice during the bake. Serve rice, tofu, broccoli, the thickened glaze, and the sesame seeds.', '["jasmine rice","sesame seeds","broccoli florets","extra-firm tofu"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_thai-basil-eggplant-stir-fry_v1', 1, 'Stir-fry eggplant', 'High heat with 1 tbsp oil until browned and tender, 6–8 min.', '["Japanese eggplant","neutral oil"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_thai-basil-eggplant-stir-fry_v1', 2, 'Season', 'Add garlic, soy, basil off heat.', '["Thai basil","garlic"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_thai-basil-eggplant-stir-fry_v1', 3, 'Serve', 'Serve over rice.', '["jasmine rice"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_thai-basil-eggplant-stir-fry_v2', 1, 'Cook the rice', 'Rinse the jasmine rice. Bring it to a boil with the water and the kosher salt. Cover, turn the heat to low, and simmer 15 minutes. Rest it covered off the heat 5 minutes, then fluff. The eggplant browns while this rice simmers and rests, including a second batch if the pan is crowded, so the rice does not have to finish before the skillet starts. This is the starch for all 4 servings. v1 said only for serving.', '["jasmine rice","water","kosher salt"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_thai-basil-eggplant-stir-fry_v2', 2, 'Brown the eggplant', 'While the rice simmers and rests, heat a wide skillet over high heat with 2 tbsp of the neutral oil. Add the Japanese eggplant in a single layer, in two batches if it would crowd. Stir-fry until browned and tender, 6-8 minutes per batch. The center of a piece should be creamy, with no raw white spongy core. Crowding will steam it instead of browning it.', '["Japanese eggplant","neutral oil"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_thai-basil-eggplant-stir-fry_v2', 3, 'Season', 'Add the remaining 1 tbsp neutral oil. Add the garlic and cook 30 seconds, until fragrant. Do not add the garlic off the heat; v1 did, and it stays harsh. Add the soy sauce and toss to coat. Take the pan off the heat and stir in the Thai basil until just wilted. There is no chili, no curry paste, and no fish sauce in this version.', '["garlic","soy sauce","Thai basil","neutral oil"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_thai-basil-eggplant-stir-fry_v2', 4, 'Serve', 'Serve the eggplant and basil over the rice. Four servings.', '["jasmine rice"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_thai-red-curry-kabocha_v1', 1, 'Cook the rice', 'Rinse the jasmine rice. Cook with water per package directions (typically 1.5 cups rice to about 2.25 cups water), covered, until tender, about 15 minutes, then rest 5 minutes off heat. Start this before or while the curry so rice is ready at plating.', '["jasmine-rice"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_thai-red-curry-kabocha_v1', 2, 'Press and brown the tofu', 'Press the tofu 10 minutes under a plate. Cut into 3/4-inch cubes. Pat dry and season with 1/4 tsp of the kosher salt. Heat 1 tbsp coconut oil in a wide pot or deep skillet over medium-high. Brown the tofu on two sides until golden, about 6 minutes total. Transfer to a plate.', '["extra-firm-tofu","kosher-salt","coconut-oil"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_thai-red-curry-kabocha_v1', 3, 'Bloom the vegetarian curry paste', 'Reduce heat to medium. Add the remaining 1 tbsp coconut oil. Add the vegetarian/vegan Thai red curry paste. Cook, stirring, until fragrant and the oil takes on red color, about 1 to 2 minutes. Do not use a paste that lists shrimp paste or fish sauce.', '["coconut-oil","vegetarian-red-curry-paste"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_thai-red-curry-kabocha_v1', 4, 'Simmer kabocha in coconut curry', 'Stir in the coconut milk, water, brown sugar, and remaining 1/2 tsp kosher salt. Add the kabocha chunks. Bring to a simmer. Cover and cook until kabocha is tender when pierced, about 12 to 15 minutes. No fish sauce at any point.', '["full-fat-coconut-milk","water","brown-sugar","kosher-salt","kabocha-squash"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_thai-red-curry-kabocha_v1', 5, 'Add pepper, tofu, spinach', 'Stir in the red bell pepper and the browned tofu. Simmer uncovered 3 to 4 minutes until the pepper softens slightly but stays bright. Fold in the baby spinach until wilted, about 1 minute. Stir in the lime juice. Taste for salt — adjust with salt only, never fish sauce.', '["red-bell-pepper","extra-firm-tofu","baby-spinach","lime-juice","kosher-salt"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_thai-red-curry-kabocha_v1', 6, 'Finish and serve', 'Take off the heat. Fold in most of the Thai basil leaves. Serve the curry over jasmine rice. Garnish with remaining basil and lime wedges. Each serving is curry with tofu and kabocha over rice. kitchen_tested is false.', '["fresh-thai-basil","jasmine-rice","lime-wedges","extra-firm-tofu","kabocha-squash"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_vietnamese-chicken-pho_v1', 1, 'Char onion and ginger', 'Heat a dry 12-inch skillet over medium-high. Place the halved unpeeled yellow onion cut-side down and the halved ginger cut-side down. Char until blackened in spots and fragrant, about 5 minutes per side for the onion and 4 minutes for the ginger, turning once. Transfer to a plate. Do not add oil.', '["yellow-onion","fresh-ginger"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_vietnamese-chicken-pho_v1', 2, 'Toast spices and start the stock', 'In a large stockpot over medium heat, toast the star anise, cinnamon stick, whole cloves, and coriander seeds until fragrant, about 1 minute. Add the 12 cups water, the bone-in chicken thighs, the charred onion, and the charred ginger. Bring to a boil over high heat, then reduce to a gentle simmer. Skim foam. Simmer uncovered until the chicken is cooked through and the broth tastes of chicken and spice, about 35 minutes. The thickest thigh should read 175 F near the bone.', '["star-anise","cinnamon-stick","whole-cloves","coriander-seeds","water","bone-in-chicken-thighs","yellow-onion","fresh-ginger"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_vietnamese-chicken-pho_v1', 3, 'Pull chicken and season broth', 'Lift the chicken to a board. Strain the broth into a clean pot; discard the solids. Return the clear broth to a simmer. Stir in the fish sauce, kosher salt, and sugar. Taste; the broth should be savory and lightly sweet, not salty-flat. Keep at a bare simmer. When the chicken is cool enough to handle, discard skin and bones. Shred the meat into bite-size strips.', '["bone-in-chicken-thighs","fish-sauce","kosher-salt","sugar"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_vietnamese-chicken-pho_v1', 4, 'Soak and soften the rice noodles', 'Place the dried flat rice noodles in a large bowl. Cover with very hot tap water and soak until pliable but not mushy, about 8 to 12 minutes depending on brand. Drain. Do not boil them in the pho broth.', '["dried-rice-noodles"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_vietnamese-chicken-pho_v1', 5, 'Assemble bowls', 'Divide the drained noodles among 4 deep bowls. Top with shredded chicken and the thinly sliced raw yellow onion. Ladle about 2 cups of very hot broth over each bowl so the noodles finish softening and the chicken warms through, about 1 minute in the bowl. The broth must be steaming hot when served.', '["dried-rice-noodles","bone-in-chicken-thighs","yellow-onion","water"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_vietnamese-chicken-pho_v1', 6, 'Finish with herbs and lime', 'Scatter the sliced scallions, chopped cilantro, and Thai basil leaves over each bowl. Serve with lime wedges and optional jalapeño slices on the side. Each serving is noodles, chicken, hot broth, and herbs. No bean sprouts are required. kitchen_tested is false.', '["scallions","fresh-cilantro","fresh-thai-basil","lime","fresh-jalapeno"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_white-bean-kale-soup_v1', 1, 'Sauté fennel', 'Soften fennel in oil over medium heat 5 min.', '["fennel","neutral oil"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_white-bean-kale-soup_v1', 2, 'Simmer', 'Add beans, broth, tomatoes; simmer 20 min.', '["cannellini beans","vegetable broth"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_white-bean-kale-soup_v1', 3, 'Wilt kale', 'Stir in kale until tender; season.', '["kale"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_white-bean-kale-soup_v2', 1, 'Saute the fennel', 'Soften the sliced fennel in the oil over medium heat for 5 minutes. This is a pot on the stove, not a sheet pan.', '["fennel","neutral oil"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_white-bean-kale-soup_v2', 2, 'Simmer', 'Add the drained beans, broth, and diced tomatoes with their liquid. Simmer 20 minutes.', '["cannellini beans","vegetable broth","diced tomatoes"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_white-bean-kale-soup_v2', 3, 'Wilt the kale and season', 'Stir in the kale and cook about 5 minutes, until tender. Stir in the kosher salt and black pepper. Do not add cheese, sausage, cream, or bread.', '["kale","kosher salt","black pepper"]');
