INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_citrus-fennel-arctic-char_v2', 'rcp_citrus-fennel-arctic-char', 'citrus-fennel-arctic-char', 2, 'Citrus Fennel Arctic Char', 'Roasted arctic char on sheet-pan fennel, finished with fresh dill and orange zest and juice.', 4, 15, 27, 42, 'Easy', 'none', 'Thickest part just opaque, flakes with a fork, 140-145 F. Not chalky. Fennel edges softened and starting to brown.', '["roast"]', '["dairy-free"]', '{"butter":"Do not swap the olive oil for butter. That would drop the dairy-free claim.","lemon":"Do not swap the orange for lemon. The citrus in this dish is orange."}', '[]', 'published', 'unpublished_curator_draft', 'global', NULL, '302fbc0a6026dc84c3a4514bd7792a4b4f619d8888b6f643ad4fdf756e97ddfa', 'flavorweave-legacy-catalog-package', 'catalog/citrus-fennel-arctic-char/v2.json', '2026-10-04T00:00:00.000Z');
