INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_crispy-fish-tacos-cabbage-slaw_v2', 'rcp_crispy-fish-tacos-cabbage-slaw', 'crispy-fish-tacos-cabbage-slaw', 2, 'Crispy Fish Tacos with Cabbage Slaw', 'Cornmeal-crusted pan-fried cod in corn tortillas with a cabbage-carrot slaw and dairy-free crema.', 4, 15, 20, 35, 'Easy', 'none', 'Crust golden. Cod opaque, flakes easily, 145 F in the center of a strip. Not chalky.', '["stovetop"]', '["dairy-free"]', '{"crema":"Store-bought dairy-free crema, or 1/2 cup vegan mayo plus the juice of 1/2 lime. Do not use sour cream or yogurt.","soy":"Some vegan mayos and dairy-free cremas contain soy. Soy is not a confirmed allergen until the brand is known."}', '[]', 'published', 'unpublished_curator_draft', 'global', NULL, 'a7a3ddc84180cbb4866689f1e7723293454ae8701b927406f6329db0ca688292', 'flavorweave-legacy-catalog-package', 'catalog/crispy-fish-tacos-cabbage-slaw/v2.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_crispy-skillet-chicken-sandwiches_v1', 'rcp_crispy-skillet-chicken-sandwiches', 'crispy-skillet-chicken-sandwiches', 1, 'Crispy Skillet Chicken Sandwiches', 'Pound-thin chicken cutlets seared in a skillet and stacked on rolls with lemon-dijon mayonnaise, lettuce, and tomato.', 4, 12, 16, 28, 'weeknight', 'Skillet over medium-high; lower to medium only if the crust darkens before the center is done.', '165°F in the center of each cutlet. Color is not the doneness test.', '[]', '[]', 'null', '[{"component_id":"lemon-dijon-mayonnaise","name":"lemon-dijon mayonnaise","made_in_recipe":true,"store_bought":false,"built_from_store_bought":["mayonnaise","dijon mustard"],"ingredients":["mayonnaise","dijon mustard","lemon","fresh parsley","garlic","kosher salt"]}]', 'published', 'draft', 'global', NULL, '73d7df15f282e692ec98693b3006e2fc1f8ad81884d6f2af11d4fa25896de293', 'flavorweave-catalog-package', 'catalog/crispy-skillet-chicken-sandwiches/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_ethiopian-beef-tibs_v1', 'rcp_ethiopian-beef-tibs', 'ethiopian-beef-tibs', 1, 'Ethiopian Berbere Beef Tibs', 'Cubed beef quickly sautéed with onion, garlic, ginger, and berbere until deeply spiced and browned, finished with tomato and herbs. Served with rice or greens (injera optional if available).', 4, 15, 25, 40, 'moderate', 'Medium-high to sear beef; medium for onion base; medium-high to finish. No oven. No grill required.', 'Beef cubes browned outside, medium inside (~135–140 F). Onions soft and brick-red with berbere. Tomato melted into the base. Not a long braise. kitchen_tested is false.', '[]', '[]', 'null', '[{"component_id":"berbere-beef","name":"berbere-seasoned beef cubes","made_in_recipe":true,"store_bought":false,"ingredients":["beef sirloin","berbere","kosher salt","black pepper"]},{"component_id":"onion-berbere-base","name":"onion berbere base","made_in_recipe":true,"store_bought":false,"ingredients":["yellow onion","garlic","fresh ginger","berbere","smoked paprika","tomato","neutral oil"]}]', 'published', 'draft', 'global', NULL, 'cd8a40a75678e53f7fc753d79a25a5f4d9e3272916dd4ac04c3be754edf74079', 'flavorweave-catalog-package', 'catalog/ethiopian-beef-tibs/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_garlic-tomato-mussels_v1', 'rcp_garlic-tomato-mussels', 'garlic-tomato-mussels', 1, 'Garlic Tomato Mussels with Grilled Bread', 'Mussels steamed in a garlic and crushed-tomato broth, finished with parsley and lemon, with oil-brushed bread toasted in a skillet.', 4, 15, 13, 28, 'weeknight', 'Medium for the onion and garlic, then a 4-minute simmer, then medium-high under a lid for the mussels. Bread toasts over medium-high.', 'Mussels are done when the shells open, usually 4 to 6 minutes. Discard any that stay closed. Do not cook them until they shrink.', '[]', '[]', 'null', '[{"component_id":"tomato-garlic-broth","name":"tomato garlic broth","made_in_recipe":true,"store_bought":false,"note":"Built in the pot from the listed aromatics, canned crushed tomatoes, and dry white wine. Those two store-bought inputs are labeled on the ingredients. There is no separate bottled sauce.","ingredients":["olive oil","onion","garlic","red pepper flakes","crushed tomatoes","dry white wine","kosher salt","black pepper"]}]', 'published', 'draft', 'global', NULL, '2b17dbd634803c9c8d3c3c2da8ce6c95e53d96c34df5e9ef9d10cbcf367e2cee', 'flavorweave-catalog-package', 'catalog/garlic-tomato-mussels/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_ginger-glazed-tempeh-plate_v1', 'rcp_ginger-glazed-tempeh-plate', 'ginger-glazed-tempeh-plate', 1, 'Ginger-Glazed Tempeh with Broccolini', 'Sliced tempeh pan-seared then glazed with ginger, garlic, tamari, and maple, plated with blistered broccolini and rice. No peanut.', 4, 15, 20, 35, 'easy', 'Medium for tempeh sear; medium-high for broccolini; medium for glaze. No oven required.', 'Tempeh deep golden and coated in syrupy ginger-maple glaze. Broccolini tender-crisp with blistered tips. Rice hot. kitchen_tested is false.', '[]', '[]', 'null', '[{"component_id":"ginger-maple-tamari-glaze","name":"ginger-maple tamari glaze","made_in_recipe":true,"store_bought":false,"ingredients":["tamari","maple syrup","fresh ginger","garlic","rice vinegar","water"]},{"component_id":"seared-tempeh","name":"seared glazed tempeh","made_in_recipe":true,"store_bought":false,"ingredients":["tempeh","ginger-maple tamari glaze","neutral oil"]}]', 'published', 'draft', 'global', NULL, '9021fbb320e1e5d4d625ffd02d6a7ba3803589992aa5521d5df520f0a24bfcbf', 'flavorweave-catalog-package', 'catalog/ginger-glazed-tempeh-plate/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_ginger-scallion-fish-packets_v1', 'rcp_ginger-scallion-fish-packets', 'ginger-scallion-fish-packets', 1, 'Ginger Scallion Fish Packets', NULL, 4, 15, 25, 40, 'Easy', NULL, NULL, '["stovetop"]', '["fish","finfish","dairy-free"]', 'null', '[]', 'retired', 'published', 'global', NULL, '409c073672fa25708f809d70803fd9587a4757449974d46921ea68c57ab58c40', 'flavorweave-legacy-catalog-package', 'catalog/ginger-scallion-fish-packets/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_ginger-scallion-fish-packets_v2', 'rcp_ginger-scallion-fish-packets', 'ginger-scallion-fish-packets', 2, 'Ginger Scallion Fish Packets', 'Foil packets of white fish and halved bok choy with ginger, scallion, and soy, baked until the fish flakes, served with rice.', 4, 15, 20, 35, 'Easy', 'Oven 400 F for the packets. Rice simmers, covered, on the stove and overlaps the bake.', 'Fish flakes easily and is opaque in the center, 18 to 20 minutes at 400 F. Bok choy is tender. Rice is tender and the water is absorbed. Not a rare fillet and not a sear.', '["oven","stovetop"]', '[]', 'null', '[]', 'published', 'draft', 'global', NULL, '74b4b53dff88c4203b6e8227e879445be8572950d3ca430e8c77423276f83b72', 'flavorweave-legacy-audit-draft', 'catalog/ginger-scallion-fish-packets/v2.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_gochujang-grilled-flank-steak_v1', 'rcp_gochujang-grilled-flank-steak', 'gochujang-grilled-flank-steak', 1, 'Gochujang Grilled Flank Steak', 'Thin-sliced grilled flank steak in a short gochujang marinade, with a sharp cucumber and scallion salad.', 4, 25, 25, 50, 'moderate', 'Direct grill heat, about 450–500°F.', '130–135°F in the center for medium-rare, then a 5-minute rest. Slice against the grain.', '[]', '[]', 'null', '[{"component_id":"gochujang-marinade","name":"gochujang marinade","made_in_recipe":true,"store_bought":false,"ingredients":["gochujang","soy sauce","rice vinegar","toasted sesame oil","brown sugar","garlic","fresh ginger","black pepper","scallions"]},{"component_id":"scallion-cucumber-salad","name":"scallion cucumber salad","made_in_recipe":true,"store_bought":false,"ingredients":["cucumber","scallions","rice vinegar","toasted sesame oil","kosher salt","sesame seeds"]}]', 'published', 'draft', 'global', NULL, '7b3489e7f9a4cc9dd3fe40795b887d4c1d3cb0efcf548251b4f4eaa8d2ad161c', 'flavorweave-catalog-package', 'catalog/gochujang-grilled-flank-steak/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_greek-chicken-souvlaki_v1', 'rcp_greek-chicken-souvlaki', 'greek-chicken-souvlaki', 1, 'Greek Chicken Souvlaki with Cucumber Salad', 'Lemon-oregano marinated chicken thigh skewers grilled or broiled, served with a dairy-free cucumber-tomato-dill salad.', 4, 15, 35, 50, 'moderate', 'Grill or grill pan medium-high, or oven broiler on high 6 inches from element. Broiler preheat 5 minutes overlaps skewer threading.', 'Chicken 165 F in the thickest piece, browned in spots. Salad crisp, not watery. kitchen_tested is false.', '[]', '[]', 'null', '[{"component_id":"lemon-oregano-marinade","name":"lemon-oregano marinade","made_in_recipe":true,"store_bought":false,"ingredients":["olive oil","lemon juice","garlic","dried oregano","kosher salt","black pepper"]},{"component_id":"cucumber-tomato-salad","name":"cucumber tomato salad","made_in_recipe":true,"store_bought":false,"ingredients":["English cucumber","cherry tomatoes","red onion","fresh dill","lemon juice","olive oil","kosher salt"]}]', 'published', 'draft', 'global', NULL, '29d0a9d3c34cd74c5b7cdff580996a38972aa197fa1476fae4f81b910e7ea4b5', 'flavorweave-catalog-package', 'catalog/greek-chicken-souvlaki/v1.json', '2026-10-04T00:00:00.000Z');
