INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_grilled-peach-burrito-bowl_v2', 'rcp_grilled-peach-burrito-bowl', 'grilled-peach-burrito-bowl', 2, 'Grilled Peach Burrito Bowl', 'Grilled peach slices over lime-seasoned rice and cumin black beans, with pickled red onion and cilantro.', 4, 15, 10, 25, 'Easy', 'none', 'Peach slices charred at the edges and still holding their shape, not collapsed. Beans heated through. Rice warm.', '["grill","stovetop"]', '["plant","dairy-free"]', '{"pickled red onion":"Use store-bought. A quick pickle is not specified here because v1 gave no brine.","rice":"Start from 3 cups cooked rice. Cooking rice from raw is extra time and is not inside the 25 minutes."}', '[]', 'published', 'unpublished_curator_draft', 'global', NULL, 'd1d6672fa3c6e5b3cbda937ce398706b31cbf5201903b88daf3b16388aed2a38', 'flavorweave-legacy-catalog-package', 'catalog/grilled-peach-burrito-bowl/v2.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_grilled-swordfish-olive-caper_v1', 'rcp_grilled-swordfish-olive-caper', 'grilled-swordfish-olive-caper', 1, 'Grilled Swordfish with Olive-Caper Relish', 'Thick grilled swordfish steaks and grilled fennel, with a chopped olive, caper, and anchovy relish.', 4, 18, 28, 46, 'moderate', 'Direct grill heat, about 450-500 F.', 'Pull swordfish at 130-135 F in the center, then rest 3 minutes. The edge should be opaque and the very center just losing its translucence, flaking under pressure, not chalky. 145 F is the more conservative seafood temperature and will be drier; add about 1 minute per side for that target. The written target is 130-135 F. kitchen_tested is false.', '[]', '[]', 'null', '[{"component_id":"olive-caper-relish","name":"olive-caper relish","made_in_recipe":true,"store_bought":false,"ingredients":["pitted green olives","capers","anchovy fillets","garlic","lemon","fresh parsley","olive oil","kosher salt","red pepper flakes"]}]', 'published', 'draft', 'global', NULL, 'cc9f939788eaf1f150c2c383476f0fd74873d2cc43b549d7578bfa2042f1acf9', 'flavorweave-catalog-package', 'catalog/grilled-swordfish-olive-caper/v1.json', '2026-10-04T00:00:00.000Z');
