INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_herb-vegetable-pot-pie_v1', 'rcp_herb-vegetable-pot-pie', 'herb-vegetable-pot-pie', 1, 'Herb Vegetable Pot Pie', 'Carrots, parsnips, and Yukon Gold potatoes in a thyme-rosemary butter-and-cream gravy, baked under an egg-washed all-butter puff pastry lid until golden and flaky.', 4, 20, 67, 87, 'moderate', 'Oven 400 F, rack in center, preheated during prep. Stovetop medium for butter and vegetables; medium-low simmer for the gravy. Bake on a rimmed sheet pan to catch bubbling.', 'Pastry puffed, flaky, and deep golden-brown (not pale, not scorched at the corners). Gravy bubbling through the vents and thick enough to coat a spoon after the 10-minute rest. Potato, carrot, and parsnip cubes fork-tender. kitchen_tested is false.', '[]', '[]', 'null', '[{"component_id":"herb-root-vegetable-gravy-filling","name":"herb root-vegetable gravy filling","made_in_recipe":true,"store_bought":false,"ingredients":["unsalted butter","yellow onion","celery","carrots","parsnips","Yukon Gold potatoes","garlic","fresh thyme","fresh rosemary","all-purpose flour","vegetable stock","heavy cream","frozen peas","fresh parsley","kosher salt","black pepper"]},{"component_id":"puff-pastry-lid","name":"egg-washed all-butter puff pastry lid","made_in_recipe":false,"store_bought":true,"contract":"Store-bought frozen all-butter puff pastry (wheat + butter). Egg wash made in recipe.","ingredients":["all-butter puff pastry","egg","water","all-purpose flour (for dusting)"]}]', 'published', 'draft', 'global', NULL, '54679f201082d73800ce0b9ef70d0ac809c3744b0bcfa5c96ddd8aa33ce67319', 'flavorweave-catalog-package', 'catalog/herb-vegetable-pot-pie/v1.json', '2026-10-04T00:00:00.000Z');
