INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_herbed-polenta-tomato-stew_v2', 'rcp_herbed-polenta-tomato-stew', 'herbed-polenta-tomato-stew', 2, 'Herbed Polenta with Tomato Stew', 'Soft stovetop polenta with a burst cherry-tomato and white-bean stew finished with fresh rosemary.', 4, 10, 22, 32, 'Easy', 'none', 'Polenta thick and soft, pulling from the side of the pan. Tomatoes burst; stew spoonable, not watery.', '["stovetop"]', '["plant","dairy-free"]', '{"butter or cheese":"Do not add butter or cheese. Either one would drop the dairy-free claim.","rosemary":"Use fresh. Do not use 1 tbsp dried rosemary."}', '[]', 'published', 'unpublished_curator_draft', 'global', NULL, '5ce29af8c866dd99144182c89c2e85c5f60345a378ff2f9e3b89e6dcde1bfcd4', 'flavorweave-legacy-catalog-package', 'catalog/herbed-polenta-tomato-stew/v2.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_jamaican-jerk-pork-chops_v1', 'rcp_jamaican-jerk-pork-chops', 'jamaican-jerk-pork-chops', 1, 'Jamaican Jerk Pork Chops with Pineapple Slaw', 'Bone-in pork chops coated in a blended Scotch-bonnet jerk paste, skillet-seared, served with crunchy pineapple-cabbage slaw.', 4, 20, 32, 52, 'moderate', 'Medium skillet for the chops; lower to medium-low if the paste threatens to burn. No oven.', 'Pork chops 145 F in the thickest part away from bone, then 5-minute rest. Paste deep brown, not bitter black. Slaw crunchy. kitchen_tested is false.', '[]', '[]', 'null', '[{"component_id":"jerk-paste","name":"jerk paste","made_in_recipe":true,"store_bought":false,"ingredients":["scallions","fresh thyme","garlic","fresh ginger","Scotch bonnet pepper","ground allspice","ground cinnamon","ground nutmeg","light brown sugar","tamari","lime juice","olive oil","kosher salt","black pepper"]},{"component_id":"pineapple-slaw","name":"pineapple slaw","made_in_recipe":true,"store_bought":false,"ingredients":["green cabbage","fresh pineapple","red bell pepper","fresh cilantro","lime","kosher salt"]}]', 'published', 'draft', 'global', NULL, 'b2641c33977d1b842c138100dc678d78b725d277acc551ad74443cbad6c777d9', 'flavorweave-catalog-package', 'catalog/jamaican-jerk-pork-chops/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_kimchi-fried-rice_v1', 'rcp_kimchi-fried-rice', 'kimchi-fried-rice', 1, 'Kimchi Fried Rice', 'Day-old rice stir-fried with chopped plant kimchi, kimchi brine, scallions, gochujang, and sesame oil. Vegan kimchi contracted; no egg, no bacon.', 4, 10, 15, 25, 'easy', 'Medium-high skillet or wok throughout. No oven.', 'Rice hot, red from kimchi, lightly toasted in spots. Kimchi jammy at edges. No raw onion crunch left in the base. kitchen_tested is false.', '[]', '[]', 'null', '[{"component_id":"kimchi-gochujang-base","name":"kimchi gochujang skillet base","made_in_recipe":true,"store_bought":false,"ingredients":["plant kimchi","kimchi brine","gochujang","soy sauce","garlic","onion","sugar"]},{"component_id":"kimchi-fried-rice","name":"kimchi fried rice","made_in_recipe":true,"store_bought":false,"ingredients":["day-old rice","kimchi gochujang skillet base","toasted sesame oil"]}]', 'published', 'draft', 'global', NULL, '3e5930224803e6263e94a5a6624caa3ee1e0703d717505e341849939c4c4bda4', 'flavorweave-catalog-package', 'catalog/kimchi-fried-rice/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_korean-soft-tofu-stew_v1', 'rcp_korean-soft-tofu-stew', 'korean-soft-tofu-stew', 1, 'Korean Soft Tofu Stew', 'Soft tofu simmered in a spicy gochugaru broth with plant kimchi, zucchini, and mushrooms. No egg, no seafood, no meat.', 4, 15, 21, 36, 'easy', 'Medium for aromatics and chili bloom. Medium-high to bring the broth up, then medium simmer. Gentle simmer for the tofu. No oven.', 'Zucchini tender-crisp after about 8 minutes of simmer. Soft tofu hot through after about 5 gentle minutes, still in large spoonable chunks, not scrambled. Broth spicy, sour from plant kimchi, savory from soy and gochujang. kitchen_tested is false.', '[]', '[]', 'null', '[{"component_id":"spicy-kimchi-broth","name":"spicy kimchi broth","made_in_recipe":true,"store_bought":false,"ingredients":["neutral oil","toasted sesame oil","yellow onion","garlic","fresh ginger","shiitake mushrooms","gochugaru","gochujang","plant kimchi","zucchini","vegetable stock","water","soy sauce","sugar","kosher salt","black pepper"]}]', 'published', 'draft', 'global', NULL, 'ef5725ef032333f4cd756a5b531958e1b2d47ca1afc0ddef45e6d5bdb1b33d36', 'flavorweave-catalog-package', 'catalog/korean-soft-tofu-stew/v1.json', '2026-10-04T00:00:00.000Z');
