INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_lemon-pea-risotto_v1', 'rcp_lemon-pea-risotto', 'lemon-pea-risotto', 1, 'Lemon Pea Risotto', 'Arborio rice stirred with hot vegetable stock until creamy, finished with peas, lemon, butter, and microbial-rennet Parmesan.', 4, 12, 28, 40, 'moderate', 'Stock held at a bare simmer. Risotto pot over medium for shallot and toast, then medium to medium-low while ladling. Finish off heat.', 'Rice al dente with creamy starch suspension. Peas hot and bright. Spreads slowly on a plate. Lemon bright, not bitter from too much pith. kitchen_tested is false.', '[]', '[]', 'null', '[{"component_id":"lemon-parmesan-finish","name":"lemon-Parmesan finish","made_in_recipe":true,"store_bought":false,"ingredients":["unsalted butter","vegetarian Parmesan","lemon zest","lemon juice","black pepper","kosher salt","fresh parsley","frozen peas"]}]', 'published', 'draft', 'global', NULL, 'd16f1610019344376dc644f732a6e3069a970be6544f53f70dad9dbf6e40e6cd', 'flavorweave-catalog-package', 'catalog/lemon-pea-risotto/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_lentil-stuffed-cabbage_v1', 'rcp_lentil-stuffed-cabbage', 'lentil-stuffed-cabbage', 1, 'Lentil-Stuffed Cabbage with Tomato Sauce', 'Cabbage leaves rolled around brown lentils and parcooked rice, baked in a tomato sauce made from crushed tomatoes.', 4, 35, 106, 141, 'long', 'Stove for the lentils, rice, filling, and sauce. Oven 375 F for the covered bake, then uncovered.', 'Lentils are simmered only until tender with a bite, then finish in the oven. Rolls bake 40 minutes covered and 10 minutes uncovered at 375 F until the center filling is hot and steaming and the leaf edges show browned spots.', '[]', '[]', 'null', '[{"component_id":"lentil-rice-filling","name":"lentil-rice filling","made_in_recipe":true,"store_bought":false,"ingredients":["brown lentils","long-grain white rice","yellow onion","garlic","olive oil","kosher salt","black pepper","sweet paprika","fresh parsley"]},{"component_id":"tomato-sauce","name":"tomato sauce","made_in_recipe":true,"store_bought":false,"ingredients":["crushed tomatoes","yellow onion","garlic","olive oil","water","red wine vinegar","brown sugar","kosher salt","green cabbage"]}]', 'published', 'draft', 'global', NULL, '3753b08203ecb1b7d989bce848e604b74befd260ec1e6185c3e484a966605fa9', 'flavorweave-catalog-package', 'catalog/lentil-stuffed-cabbage/v1.json', '2026-10-04T00:00:00.000Z');
