INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_pan-fried-pork-dumplings_v1', 'rcp_pan-fried-pork-dumplings', 'pan-fried-pork-dumplings', 1, 'Pan-Fried Pork and Cabbage Dumplings', 'Ground pork and napa cabbage dumplings, pleated by hand and pan-fried to a crisp golden bottom with a short covered steam, served with a simple soy-vinegar dipping sauce.', 4, 39, 24, 63, 'moderate', 'Medium-high to preheat the oil and fry the bottoms; medium for the covered steam; medium uncovered to evaporate water and re-crisp. Stovetop only. No deep-fry, no boil, no oven.', 'Bottoms deep golden and crisp; tops tender and translucent, not gummy-white. Filling firm, juicy, no pink, 160 F if checked. Water fully evaporated before plating so bottoms stay crisp. kitchen_tested is false.', '[]', '[]', 'null', '[{"component_id":"pork-cabbage-filling","name":"pork and napa cabbage filling","made_in_recipe":true,"store_bought":false,"ingredients":["ground pork","napa cabbage","scallions","fresh ginger","garlic","soy sauce","toasted sesame oil","granulated sugar","ground white pepper","kosher salt","cornstarch","water"]},{"component_id":"dumpling-wrappers","name":"round dumpling wrappers","made_in_recipe":false,"store_bought":true,"contract":"Store-bought wheat-and-water round dumpling wrappers; egg-free (no yellow wonton/egg-roll wrappers).","ingredients":["round dumpling wrappers"]},{"component_id":"soy-vinegar-dip","name":"soy-vinegar dipping sauce","made_in_recipe":true,"store_bought":false,"ingredients":["soy sauce","unseasoned rice vinegar","toasted sesame oil","scallion green"]}]', 'published', 'draft', 'global', NULL, 'b5303eedfe7ea477b787e0287a4912869ef86a9c753b5bc0a8a7b69742d61639', 'flavorweave-catalog-package', 'catalog/pan-fried-pork-dumplings/v1.json', '2026-10-04T00:00:00.000Z');
