INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_potato-leek-gratin_v1', 'rcp_potato-leek-gratin', 'potato-leek-gratin', 1, 'Potato and Leek Gratin', 'Thinly sliced potatoes and leeks baked in a cream and cheese custard until the center is tender and the top is browned.', 4, 15, 55, 70, 'moderate', 'Oven 400 F. Leeks sauté over medium during the preheat. Bake on the middle rack.', 'Center potato slice takes a knife with little resistance. Cream is bubbling at the edges and thickened, not watery. Cheese on top is browned in patches. No breadcrumb crust. Rest 5 minutes. Written bake is 40 minutes at 400 F for 1/8-inch slices. kitchen_tested is false. Extra time beyond 40 minutes, if the center is still firm, is not included in the 70-minute total.', '[]', '[]', 'null', '[{"component_id":"cream-cheese-custard","name":"cream-cheese custard","made_in_recipe":true,"store_bought":false,"ingredients":["heavy cream","vegetarian Gruyère","garlic","kosher salt","black pepper","ground nutmeg","fresh thyme"]}]', 'published', 'draft', 'global', NULL, '15199310bfad63c4441c2efd075c865aa1a8a4f88b3e8a7e3d408b5e3bc13fd8', 'flavorweave-catalog-package', 'catalog/potato-leek-gratin/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_roasted-butternut-farro-plate_v1', 'rcp_roasted-butternut-farro-plate', 'roasted-butternut-farro-plate', 1, 'Roasted Butternut Plate with Farro and Lemon-Herb Dressing', 'Oven-roasted butternut wedges beside simmered pearled farro, with a lemon, garlic, and parsley dressing spooned over the plate.', 4, 15, 35, 50, 'weeknight', 'Oven 425 F for the squash. Farro simmers on the stove. Dressing is not cooked.', 'Squash is done when the edges are browned and a knife meets no resistance, about 35 minutes, flipped at 20. Pearled farro is done when the grains are tender and some have split, about 30 minutes. This recipe is pearled farro only.', '[]', '[]', 'null', '[{"component_id":"lemon-herb-dressing","name":"lemon-herb dressing","made_in_recipe":true,"store_bought":false,"ingredients":["olive oil","lemon","garlic","dijon mustard","fresh parsley","kosher salt","black pepper"]}]', 'published', 'draft', 'global', NULL, '91d562c5d0278acb0d695ef8902f57ec74ebf10488dd9e32e6dbe0eac3acaa1d', 'flavorweave-catalog-package', 'catalog/roasted-butternut-farro-plate/v1.json', '2026-10-04T00:00:00.000Z');
