INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_sesame-soba-noodle-bowl_v2', 'rcp_sesame-soba-noodle-bowl', 'sesame-soba-noodle-bowl', 2, 'Sesame Soba Noodle Bowl', 'Cold rinsed soba tossed with sesame oil, rice vinegar, and soy, topped with julienned carrot, edamame, and sesame seeds.', 4, 15, 10, 25, 'Easy', 'Boiling water for the soba. The dressing is not cooked.', 'Soba is done when tender but not mushy, 4 to 5 minutes, then rinsed cold. Edamame is already cooked and only thawed.', '["stovetop"]', '[]', 'null', '[]', 'published', 'draft', 'global', NULL, 'bd77ce7a11a7d64a3893ff31a9d0b134b72eab1e6ec62048eef5daee57a5f600', 'flavorweave-legacy-audit-draft', 'catalog/sesame-soba-noodle-bowl/v2.json', '2026-10-04T00:00:00.000Z');
