INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_sheet-pan-margherita-pizza_v1', 'rcp_sheet-pan-margherita-pizza', 'sheet-pan-margherita-pizza', 1, 'Sheet-Pan Margherita Pizza', 'Store-bought pizza dough pressed into an olive-oiled sheet pan, topped with a simple crushed-tomato sauce and torn fresh mozzarella, baked hot until crisp underneath, and finished with fresh basil.', 4, 15, 44, 59, 'easy', 'Oven 475 F, rack in the lower third, preheated about 20 minutes. Oiled heavy sheet pan directly on the rack — no pizza stone, no broiler, no grill.', 'Underside deep golden and crisp when a corner is lifted (not pale or doughy); edges golden and puffed. Fresh mozzarella melted, bubbling, lightly spotted — not separated into oil and not browned to rubber. Sauce reduced and jammy, not watery. Basil bright green, added after baking. kitchen_tested is false.', '[]', '[]', 'null', '[{"component_id":"sheet-pan-dough","name":"store-bought pizza dough base","made_in_recipe":false,"store_bought":true,"contract":"Store-bought raw pizza dough limited to wheat flour, water, yeast, salt, oil, optional sugar; no milk/egg/cheese/soy flour.","ingredients":["store-bought raw pizza dough","extra-virgin olive oil"]},{"component_id":"crushed-tomato-sauce","name":"uncooked crushed-tomato sauce","made_in_recipe":true,"store_bought":false,"ingredients":["canned crushed tomatoes","garlic","extra-virgin olive oil","kosher salt"]},{"component_id":"margherita-topping","name":"fresh mozzarella and basil topping","made_in_recipe":true,"store_bought":false,"ingredients":["fresh mozzarella","fresh basil"]}]', 'published', 'draft', 'global', NULL, 'b67d37a4dad630fc846198b27087f74c424718bcbfbc51ac1e50c706a82d3048', 'flavorweave-catalog-package', 'catalog/sheet-pan-margherita-pizza/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_skillet-shakshuka_v1', 'rcp_skillet-shakshuka', 'skillet-shakshuka', 1, 'Skillet Shakshuka', 'Eggs set in a skillet of tomato and red pepper sauce made from crushed tomatoes, peppers, onion, and ground spices.', 4, 12, 26, 38, 'easy', 'Medium for the onion, peppers, and sauce. Medium-low, covered, for the eggs. No oven.', 'Sauce holds a well after about 10 minutes of simmering. Eggs: whites fully set, no liquid white, yolks soft and glossy. Do not flip them. Firm yolks need about 2 extra covered minutes and are not the written target. kitchen_tested is false.', '[]', '[]', 'null', '[{"component_id":"tomato-pepper-sauce","name":"tomato-pepper sauce","made_in_recipe":true,"store_bought":false,"ingredients":["olive oil","yellow onion","red bell pepper","garlic","sweet paprika","ground cumin","ground coriander","canned crushed tomatoes","water","sugar","kosher salt","black pepper"]}]', 'published', 'draft', 'global', NULL, '290b42f195cffbc68d799b1c04d41d1d85757f1d5c665c02063ecdac9b4cf44c', 'flavorweave-catalog-package', 'catalog/skillet-shakshuka/v1.json', '2026-10-04T00:00:00.000Z');
