INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_spanish-chorizo-pepper-rice_v1', 'rcp_spanish-chorizo-pepper-rice', 'spanish-chorizo-pepper-rice', 1, 'Spanish Chorizo and Pepper Rice', 'One-pan Spanish-style rice cooked with sliced cured chorizo, blistered peppers, onion, garlic, smoked paprika, and tomatoes.', 4, 12, 33, 45, 'easy', 'Medium for browning chorizo and peppers; medium-high to bring to simmer; low covered for absorb. No oven. No grill.', 'Rice tender and liquid absorbed after covered cook plus 5-minute rest. Peppers blistered at edges. Chorizo browned. No raw crunchy rice. kitchen_tested is false.', '[]', '[]', 'null', '[{"component_id":"chorizo-pepper-sofrito","name":"chorizo-pepper sofrito base","made_in_recipe":true,"store_bought":false,"ingredients":["Spanish chorizo","yellow onion","red bell pepper","green bell pepper","garlic","smoked paprika","ground cumin","olive oil"]},{"component_id":"one-pan-arroz","name":"one-pan Spanish-style rice","made_in_recipe":true,"store_bought":false,"ingredients":["short-grain rice","crushed tomatoes","stock","chorizo-pepper sofrito"]}]', 'published', 'draft', 'global', NULL, '42823dc8a4aa7a319f40800229674e457b6d5a77206b61858291101ef920fd31', 'flavorweave-catalog-package', 'catalog/spanish-chorizo-pepper-rice/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_spiced-lamb-meatballs_v1', 'rcp_spiced-lamb-meatballs', 'spiced-lamb-meatballs', 1, 'Spiced Lamb Meatballs with Tomato-Herb Sauce', 'Lamb meatballs seasoned with cumin, coriander, mint, and parsley, browned and simmered in a skillet tomato-herb sauce.', 4, 18, 28, 46, 'moderate', 'Medium-high to brown. Medium for sauce aromatics. Medium-low simmer for meatballs in sauce. No oven.', 'Meatball centers 160 F. Sauce slightly thickened, spoon-coating. Herbs fresh at the finish. kitchen_tested is false.', '[]', '[]', 'null', '[{"component_id":"spiced-lamb-meatballs","name":"spiced lamb meatballs","made_in_recipe":true,"store_bought":false,"ingredients":["ground lamb","egg","panko breadcrumbs","yellow onion","garlic","fresh parsley","fresh mint","ground cumin","ground coriander","sweet paprika","red pepper flakes","kosher salt","black pepper"]},{"component_id":"tomato-herb-sauce","name":"tomato-herb sauce","made_in_recipe":true,"store_bought":false,"ingredients":["olive oil","yellow onion","garlic","tomato paste","canned crushed tomatoes","water","kosher salt","fresh parsley"]}]', 'published', 'draft', 'global', NULL, '6562f4603fb267f491201e8d5d9d4e1788077fc3368a70e8b12ac9046ada75eb', 'flavorweave-catalog-package', 'catalog/spiced-lamb-meatballs/v1.json', '2026-10-04T00:00:00.000Z');
