INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_thai-basil-eggplant-stir-fry_v2', 'rcp_thai-basil-eggplant-stir-fry', 'thai-basil-eggplant-stir-fry', 2, 'Thai Basil Eggplant Stir-Fry', 'Browned Japanese eggplant and wilted Thai basil over jasmine rice, seasoned with soy sauce and garlic.', 4, 15, 25, 40, 'Easy', 'none', 'Eggplant browned and tender, center creamy with no raw white spongy core. Basil wilted, not blackened. Rice tender.', '["stovetop"]', '["plant","dairy-free"]', '{"soy sauce":"Keep wheat-containing soy sauce. Wheat-free tamari would drop the wheat allergen and is not this version.","fish sauce":"Do not substitute fish sauce. It would drop the plant claim and add finfish."}', '[]', 'published', 'unpublished_curator_draft', 'global', NULL, '68beba3d68420477dcfad65f415afcf979577fa7ac614af8a672512a3f844256', 'flavorweave-legacy-catalog-package', 'catalog/thai-basil-eggplant-stir-fry/v2.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_thai-red-curry-kabocha_v1', 'rcp_thai-red-curry-kabocha', 'thai-red-curry-kabocha', 1, 'Thai Red Curry with Kabocha and Tofu', 'Kabocha squash and browned tofu simmered in a coconut red curry built from vegetarian Thai red curry paste — no fish sauce, no dairy.', 4, 20, 35, 55, 'moderate', 'Medium-high to brown tofu. Medium to bloom paste and simmer curry. Rice: covered simmer then rest. No oven.', 'Kabocha tender when pierced. Tofu golden on edges. Spinach wilted. Curry cohesive, coconut-red, not broken. Rice fluffy. kitchen_tested is false.', '[]', '[]', 'null', '[{"component_id":"thai-red-coconut-curry","name":"Thai red coconut curry","made_in_recipe":true,"store_bought":false,"ingredients":["coconut oil","vegetarian/vegan Thai red curry paste","full-fat coconut milk","water","light brown sugar","kosher salt","kabocha squash","red bell pepper","extra-firm tofu","baby spinach","lime juice","fresh Thai basil"]},{"component_id":"jasmine-rice","name":"jasmine rice","made_in_recipe":true,"store_bought":false,"ingredients":["uncooked jasmine rice","water"]}]', 'published', 'draft', 'global', NULL, 'f1587dbedb120dca2ec6f7c222f61833ec0c8f6c971b9e939735ab62a5a27d9a', 'flavorweave-catalog-package', 'catalog/thai-red-curry-kabocha/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_vietnamese-chicken-pho_v1', 'rcp_vietnamese-chicken-pho', 'vietnamese-chicken-pho', 1, 'Vietnamese Chicken Pho', 'Chicken simmered with charred onion, ginger, and whole spices into a clear broth, served over flat rice noodles with herbs and lime.', 4, 20, 55, 75, 'moderate', 'Dry medium-high skillet for charring. Stockpot: high to boil, then gentle simmer. No oven.', 'Chicken thighs 175 F near the bone before shredding. Broth clear, savory, lightly sweet. Rice noodles pliable, not mushy. Broth steaming hot in the bowl. kitchen_tested is false.', '[]', '[]', 'null', '[{"component_id":"pho-chicken-broth","name":"pho chicken broth","made_in_recipe":true,"store_bought":false,"ingredients":["bone-in chicken thighs","yellow onion","fresh ginger","star anise","cinnamon stick","whole cloves","coriander seeds","water","fish sauce","kosher salt","sugar"]}]', 'published', 'draft', 'global', NULL, '00a1940edde53011d94353f0d8f54fa142706cd20a9f679fb4d326b444dc3391', 'flavorweave-catalog-package', 'catalog/vietnamese-chicken-pho/v1.json', '2026-10-04T00:00:00.000Z');
