INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_white-bean-kale-soup_v2', 'rcp_white-bean-kale-soup', 'white-bean-kale-soup', 2, 'White Bean Kale Soup', 'Stovetop soup of cannellini beans, fennel, diced tomato, and kale in vegetable broth.', 4, 15, 30, 45, 'Easy', 'Medium heat to soften the fennel, then a simmer. No oven.', 'Fennel is softened at 5 minutes. The soup simmers 20 minutes. Kale is tender at about 5 minutes more. Canned beans are already cooked.', '["stovetop"]', '[]', 'null', '[]', 'published', 'draft', 'global', NULL, '38ca9abca7795e33db565657cd97efee0c706707461a9507cd55d83a5d37fcbb', 'flavorweave-legacy-audit-draft', 'catalog/white-bean-kale-soup/v2.json', '2026-10-04T00:00:00.000Z');

